window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch09"]={"id": "ch09", "title": "第九章 系统生物学", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第九章 系统生物学", "slides": [{"i": 0, "sec": "第一节 系统生物学基本概念", "title": "系统生物学导论与历史机遇", "notes": "本页为第九章开篇，介绍系统生物学在後基因组时代的地位。系统生物学通过整合基因、蛋白质、代谢物等组分及其相互作用，理解细胞复杂生物系统；通过生物、遗传或化学扰动，检测基因、蛋白质和信息通路的响应，整合数据形成描述系统结构及扰动响应的动力学模型。本章涵盖基本哲学思想、方法与技术，并以基因表达调控网络、代谢途径、信号转导通路和蛋白质相互作用网络为例介绍建模与分析理论。第一节‘系统生物学基本概念’中‘历史的机遇’指出：自1953年DNA双螺旋发现以来，分子生物学取得巨大成就，但基因组计划等产生的大量序列数据并未带来对生物系统的彻底理解，反而催生了系统生物学。因为基因与蛋白质很少单独起作用，而是组成相互作用网络行使功能；仅凭序列信息难以推断基因功能，必须将基因组或蛋白质组视为系统进行分析。", "page": 175, "level": "掌握", "img": "assets/img/ch09/p175.jpg", "anim": null, "fig": null, "points": ["系统生物学定位：后基因组时代整合基因、蛋白质、代谢物等组分及其相互作用，理解细胞复杂生物系统。", "核心方法：通过生物、遗传或化学扰动，检测基因、蛋白质和信息通路的响应，整合数据形成动力学模型。", "模型目标：描述系统结构及扰动响应，揭示复杂生命活动的系统行为。", "本章内容：基本哲学思想、方法与技术，并以基因表达调控网络、代谢途径、信号转导通路和蛋白质相互作用网络为例介绍建模与分析理论。", "第一节主题：系统生物学基本概念，从历史机遇切入。", "⚠️ 考点/易错点：系统生物学的核心定义：通过整合基因、蛋白质、代谢物等组分及其相互作用，并借助扰动实验检测响应，建立描述系统结构及扰动响应的动力学模型。"], "code": null, "lang": null, "check": {"q": "系统生物学通过整合基因、蛋白质、代谢物等组分及其相互作用来理解细胞复杂生物系统，其核心特征之一是通过什么方式检测基因、蛋白质和信息通路的响应？", "o": ["A. 仅通过显微镜观察细胞形态", "B. 通过生物、遗传或化学扰动", "C. 仅通过DNA序列比对", "D. 仅通过单一基因敲除"], "a": "B", "e": "系统生物学通过生物、遗传或化学扰动，检测基因、蛋白质和信息通路的响应，并整合数据形成动力学模型。"}, "cards": [{"front": "系统生物学的核心目标是什么？", "back": "整合基因、蛋白质、代谢物等组分及其相互作用，通过扰动检测响应，整合数据形成描述系统结构及扰动响应的动力学模型，从而理解细胞复杂生物系统。", "mnemonic": "整合组分，扰动响应，建模理解", "useImg": false}]}, {"i": 1, "sec": "第一节 系统生物学基本概念", "title": "生物还原论与生物综合论", "notes": "本页阐述系统生物学的哲学基础：还原论与综合论。还原论是20世纪后半叶生物学主流，主张研究某一功能只需寻找并鉴定直接相关的基因或蛋白质，即从整体机能到分子机制。基因组计划揭开了综合论序幕，综合论研究基因和生物大分子如何通过网络调控形成生物系统。后基因组时代需要综合全部生物信息重构生物体，综合论将成为主流。系统生物学常从简单分子模型开始，研究分子间非线性相互作用产生的系统特点，通过方程参数化实现对系统特点的真实估计（图9-1示意还原论与综合论方法：还原论从生物体到组成部件，综合论从组成部件到生物体）。物理学化学中基本粒子组装规律已明，但生物学尚不清楚基因组信息是否足以建立完整生物体系；基因组包含组分信息，但各部分间相互作用信息非常重要。传统生物学关注单个通路，系统生物学研究通路间相互作用构成复杂网络，从更高层面理解生命过程，即‘传统生物学看到树木，系统生物学看到森林’。图9-2示意细胞内多种信号转导通路相互作用。", "page": 176, "level": "掌握", "img": "assets/img/ch09/p176.jpg", "anim": null, "fig": null, "points": ["还原论：20世纪后半叶生物学主流，主张研究某一功能只需寻找并鉴定直接相关的基因或蛋白质，即从整体机能到分子机制。", "综合论：基因组计划揭开序幕，研究基因和生物大分子如何通过网络调控形成生物系统。", "后基因组时代：需要综合全部生物信息重构生物体，综合论将成为主流。", "系统生物学策略：常从简单分子模型开始，研究分子间非线性相互作用产生的系统特点。", "通过方程参数化实现对系统的定量描述与预测。", "⚠️ 考点/易错点：易混点：还原论主张从整体机能寻找直接相关的基因/蛋白质（从整体到分子），综合论则研究分子如何通过网络调控形成生物系统；后基因组时代综合论将成为主流。"], "code": null, "lang": null, "check": {"q": "关于生物还原论与生物综合论，下列说法正确的是？", "o": ["A. 还原论主张研究某一功能只需寻找并鉴定直接相关的基因或蛋白质", "B. 综合论认为生物体各组分之间没有相互作用", "C. 基因组计划揭开了还原论序幕", "D. 后基因组时代综合论将被还原论取代"], "a": "A", "e": "还原论主张从整体机能到分子机制，研究某一功能只需寻找并鉴定直接相关的基因或蛋白质；基因组计划揭开的是综合论序幕。"}, "cards": [{"front": "还原论与综合论的主要区别是什么？", "back": "还原论主张研究某一功能只需寻找并鉴定直接相关的基因或蛋白质，即从整体机能到分子机制；综合论研究基因和生物大分子如何通过网络调控形成生物系统，后基因组时代需要综合全部生物信息重构生物体。", "mnemonic": "还原找分子，综合建网络", "useImg": false}]}, {"i": 2, "sec": "第一节 系统生物学基本概念", "title": "网络层面理解细胞内生命过程（图9-2）", "notes": "本页主要为图9-2‘在网络层面对细胞内生命过程的理解’，展示细胞内多种信号转导通路之间的相互作用网络。图中包含生长因子（Growth Factors，如TGFα）、抗生长因子（Anti-growth factors）、激素（Hormones，如Bombesin）、DNA损伤（DNA damage）、死亡配体（Death ligands，如FasL）等外部信号，以及Ras、Raf、MEK、MAPK、PI3K、Akt、Rac、Rho、cdc42、JNK、p38、Stat、Bad、Bid等关键信号分子，最终影响细胞周期（Cell Cycle）、细胞骨架（Cytoskeleton）、细胞死亡（Death）等过程。该图说明细胞信号并非线性独立通路，而是高度交叉对话形成网络。读图时应关注：外部刺激如何通过受体和胞内信号分子传递；不同通路间的共享组件和交叉点；信号如何整合决定细胞命运。对于多细胞生物，还需考虑细胞间通讯。此图强调系统生物学从网络层面理解生命过程，而非孤立研究单条通路。", "page": 177, "level": "理解", "img": "assets/img/ch09/p177.jpg", "anim": null, "fig": "图9-2展示细胞内多种信号转导通路之间的相互作用网络。图中包含生长因子、抗生长因子、激素、DNA损伤、死亡配体等外部信号，以及Ras、Raf、MEK、MAPK等内部节点。该图强调信号通路之间的交叉对话，体现从网络层面理解细胞生命过程的系统生物学思想。", "points": ["图9-2主题：在网络层面对细胞内生命过程的理解，展示多种信号转导通路之间的相互作用网络。", "外部信号：生长因子（如TGFα）、抗生长因子、激素（如Bombesin）、DNA损伤、死亡配体（如FasL）等。", "内部节点：Ras、Raf、MEK、MAPK等信号转导分子。", "网络特征：信号通路并非线性独立，而是相互交叉形成复杂调控网络。", "系统生物学视角：需从网络层面理解细胞对内外信号的整合与响应。", "⚠️ 考点/易错点：图9-2展示细胞内多种信号转导通路间的相互作用网络，注意外部信号（生长因子、激素、DNA损伤、死亡配体等）与Ras、Raf、MEK、MAPK、PI3K、Akt等通路节点的对应关系。"], "code": null, "lang": null, "check": {"q": "图9-2“在网络层面对细胞内生命过程的理解”主要展示了什么？", "o": ["A. 单一DNA复制过程", "B. 细胞内多种信号转导通路之间的相互作用网络", "C. 线粒体呼吸链结构", "D. 蛋白质一级序列比对结果"], "a": "B", "e": "图9-2展示细胞内多种信号转导通路之间的相互作用网络，包含生长因子、抗生长因子、激素、DNA损伤、死亡配体等外部信号及Ras、Raf、MEK、MAPK等内部节点。"}, "cards": [{"front": "图9-2展示了什么？", "back": "图9-2展示在网络层面对细胞内生命过程的理解，包含生长因子、抗生长因子、激素、DNA损伤、死亡配体等外部信号，以及Ras、Raf、MEK、MAPK等内部节点，强调信号转导通路之间的相互作用网络。", "mnemonic": "外部信号入，内部网络联", "useImg": false}]}, {"i": 3, "sec": "第一节 系统生物学基本概念", "title": "系统生物学实验框架与基本工作流程", "notes": "本页介绍系统生物学实验框架（图9-3）和基本工作流程。图9-3显示：通过扰动（基因破坏、基因过表达、环境变化等）引起动态反应，观测基因表达谱等变化，结合生物化学、遗传学等方法。系统生物学最终目的是理解系统中整体变化的分子及其相互作用，需整合各种水平的整体测量和数学模型。基本工作框架包括四步：（一）系统结构鉴定：确定选定生物系统的所有组分，描绘结构，包括基因相互作用网络、代谢途径及细胞内外作用机制，构造初步模型；多细胞有机体还需在细胞水平理解物理结构。目的：描述统治系统行为的相互作用，精确预测给定扰动下系统行为。（二）系统行为分析：揭示系统行为方式，通过系统改变内部组分（基因突变、删除等）或外部生长条件（温度、激素、药物刺激），用大规模发现工具观测系统组分或结构变化（基因表达、蛋白质表达和相互作用、代谢途径等），并与模型整合。（三）系统控制：将实验数据与模型预测比较，修订初始模型，使预测与实验更一致。（四）系统设计：根据修正模型预测或假设，设定和实施新实验，重复（二）和（三），不断修订精炼模型。", "page": 178, "level": "掌握", "img": "assets/img/ch09/p178.jpg", "anim": null, "fig": "图9-3显示系统生物学实验框架：通过扰动引起动态反应，观测基因表达谱等变化，并结合生物化学、遗传学等方法。该图强调从扰动到观测再到模型整合的基本工作流程。", "points": ["实验框架（图9-3）：通过扰动（基因破坏、基因过表达、环境变化等）引起动态反应，观测基因表达谱等变化。", "方法整合：结合生物化学、遗传学等方法，获取多水平数据。", "最终目的：理解系统中整体变化的分子及其相互作用，需整合各种水平的整体测量和数学模型。", "基本工作框架四步之一：系统结构鉴定——确定选定生物系统的所有组分，描绘结构，包括基因相互作用网络、代谢途径及细胞内外作用机制。", "后续步骤：系统扰动、数据整合、模型构建与验证。", "⚠️ 考点/易错点：系统生物学基本工作流程四步：系统结构鉴定、系统行为测量/扰动、系统建模、模型验证与预测；最终目的是理解整体变化的分子及其相互作用，需整合各水平测量与数学模型。"], "code": null, "lang": null, "check": {"q": "系统生物学基本工作框架的第一步是？", "o": ["A. 系统结构鉴定", "B. 直接构建虚拟细胞", "C. 进行临床试验", "D. 只测量mRNA表达"], "a": "A", "e": "系统生物学基本工作框架包括四步，第一步是系统结构鉴定，即确定选定生物系统的所有组分并描绘结构。"}, "cards": [{"front": "系统生物学基本工作框架包括哪四步？", "back": "（一）系统结构鉴定：确定所有组分，描绘结构，包括基因相互作用网络、代谢途径及细胞内外作用机制；（二）系统扰动；（三）数据整合；（四）模型构建与验证。", "mnemonic": "结构、扰动、整合、建模", "useImg": false}]}, {"i": 4, "sec": "第一节 系统生物学基本概念", "title": "系统生物学测量技术与全面性准则", "notes": "本页进入第二节‘系统生物学基本技术与方法’，首先介绍测量技术。全面测量：为掌握整个生物体，需获取全面数据。目前可在mRNA水平全面测量得到基因表达谱；蛋白质表达水平及相互作用测量方法（酵母双杂交、质谱等）取得进展；干扰基因转录方法如基因敲除、RNA干扰（对线虫特别有效）；还有蛋白质高精度时空定位数据获取。线虫是充分研究的多细胞有机体，细胞系已鉴定，神经系统拓扑结构已完全描述，全基因组序列已测定，整体原位杂交技术全面揭示发育过程中基因表达模式。系统生物学测量需要全面数据并严格控制质量，供仿真、建模及系统鉴定使用。将传统实验自动化，实现高质量、高通量输出。系统、全面、精确测量是基本特征。全面性分三类：①组分的全面性：基因、蛋白质等成分必须全面测量；②时空完备性：精细时间序列和特定空间分布下获得系统行为更重要；③内容的全面性：转录水平、蛋白质相互作用强度、磷酸化、甲基化、乙酰化、定位等特征全面测量至关重要。‘系统’意味着数据必须一致、完整。以基因表达谱推导基因调控网络为例，需每个基因缺失突变和过表达产生的完整数据集，表达水平随时间和空间变化对建模重要。", "page": 179, "level": "掌握", "img": "assets/img/ch09/p179.jpg", "anim": null, "fig": null, "points": ["全面测量：为掌握整个生物体，需获取全面数据。", "mRNA水平：可全面测量得到基因表达谱。", "蛋白质水平：蛋白质表达水平及相互作用测量方法（酵母双杂交、质谱等）取得进展。", "基因干扰：基因敲除、RNA干扰（对线虫特别有效）等方法。", "线虫模型：细胞系已鉴定，神经系统拓扑结构已完全描述，全基因组序列已测定，是充分研究的多细胞有机体。", "⚠️ 考点/易错点：全面测量准则：mRNA水平可全面测量基因表达谱；蛋白质水平及相互作用用酵母双杂交、质谱等；基因干扰用基因敲除、RNA干扰（对线虫特别有效）；线虫是研究充分的多细胞模式生物。"], "code": null, "lang": null, "check": {"q": "在系统生物学测量技术中，下列哪项属于全面测量基因表达谱的常用水平？", "o": ["A. mRNA水平", "B. 仅蛋白质晶体结构水平", "C. 仅个体表型水平", "D. 仅生态系统水平"], "a": "A", "e": "目前可在mRNA水平全面测量得到基因表达谱；蛋白质表达水平及相互作用测量方法也取得进展。"}, "cards": [{"front": "系统生物学中全面测量包括哪些层面？", "back": "mRNA水平可全面测量基因表达谱；蛋白质水平及相互作用测量方法（酵母双杂交、质谱等）取得进展；基因干扰方法如基因敲除、RNA干扰；还有蛋白质高精度时空定位数据获取。", "mnemonic": "mRNA、蛋白、干扰、定位", "useImg": false}]}, {"i": 5, "sec": "第一节 系统生物学基本概念", "title": "系统结构鉴定：网络结构与参数鉴定", "notes": "本页继续介绍系统结构鉴定。为理解生物学系统，需先鉴定系统结构，包括发育过程中细胞间关系、细胞间接触、细胞膜、细胞内结构等。例如表示基因调控网络，必须鉴定网络所有组成部分及每部分功能、相互作用和相关参数，需用所有可能实验数据完成，已有实验推论可预测未知基因及相互作用，再通过实验验证。（一）网络结构的鉴定：1. 自下而上的方法：由分子间相互作用属性开始，研究这些相互作用如何导致生物体功能行为；基于独立实验数据构建网络模型，如通过文献和专门实验获取特定网络数据；适合大多数基因及调控网络已较好理解、特别已了解部分结构只需完善的情形；当大多数参数可用，主要目的是建立仿真模型，分析参数改变时系统动态特性。2. 自上而下的方法：由分子水平实验数据开始，将生物系统相关分子视为整体，在数据分析过程中得到关于生物体分子组成及功能的新假设。（二）参数鉴定：鉴定网络结构固然重要，网络中参数鉴定同样重要。本页还提到实验自动化、尖端技术（纳米技术、飞秒技术）设计下一代实验装置，四维显微成像系统收集恒定时间间隔多层共焦图像，结合整体原位杂交和单细胞表达谱，将来可实现基因调控网络完全鉴定。", "page": 180, "level": "掌握", "img": "assets/img/ch09/p180.jpg", "anim": null, "fig": null, "points": ["系统结构鉴定：需先鉴定系统结构，包括发育过程中细胞间关系、细胞间接触、细胞膜、细胞内结构等。", "基因调控网络示例：必须鉴定网络所有组成部分及每部分功能、相互作用和相关参数。", "数据利用：需用所有可能实验数据完成，已有实验推论可预测未知基因及相互作用，再通过实验验证。", "网络结构鉴定方法一：自下而上——由分子间相互作用属性开始，研究这些相互作用如何导致生物体功能行为。", "基于独立实验数据逐步构建网络模型。", "⚠️ 考点/易错点：网络结构鉴定方法：自下而上法从分子间相互作用属性出发，基于独立实验数据构建网络模型；需鉴定网络所有组分、功能、相互作用及相关参数，并用实验验证预测。"], "code": null, "lang": null, "check": {"q": "关于系统结构鉴定中的网络结构鉴定，下列哪项属于“自下而上”的方法？", "o": ["A. 由分子间相互作用属性开始，研究这些相互作用如何导致生物体功能行为", "B. 只根据整体表型猜测基因功能", "C. 完全忽略独立实验数据", "D. 只使用随机网络模型"], "a": "A", "e": "自下而上的方法由分子间相互作用属性开始，研究这些相互作用如何导致生物体功能行为，并基于独立实验数据构建网络模型。"}, "cards": [{"front": "系统结构鉴定中自下而上的方法是什么？", "back": "由分子间相互作用属性开始，研究这些相互作用如何导致生物体功能行为；基于独立实验数据逐步构建网络模型。", "mnemonic": "从分子到功能，自下而上", "useImg": false}]}, {"i": 6, "sec": "第二节 系统生物学基本技术与方法", "title": "系统生物学计算：数据、整体分析与模型", "notes": "本页属于第二节“系统生物学基本技术与方法”。系统生物学需要计算科学、数学与统计学协同，以完成生物信息的获取、存储、分析、图形化显示和模拟。首先，计算数据日益重要：除核酸和蛋白质序列外，功能基因组学与系统生物学推动了对蛋白质-蛋白质相互作用、蛋白质-DNA相互作用和代谢途径等数据的关注，例如DIP、BIND、MIP、TransFac、SCPD、KEGG、BioCyc等数据库。这些数据带来两个挑战：如何以适当格式系统存储信息，以及如何保持数据及时更新。其次，整体分析日显重要：利用表达谱、分子相互作用等数据，发展整合分析策略，识别特定生物过程中表达显著变化的基因；具有相似响应的基因常聚为功能群，通过整合表达群与蛋白质相互作用、定位等信息，可进行功能预测并寻找共调控模块。最后，计算模型越来越重要：模型最初用于解释实验观察，图示网络有助于清晰思考细胞中相互作用的复杂性。", "page": 181, "level": "理解", "img": "assets/img/ch09/p181.jpg", "anim": null, "fig": null, "points": ["计算科学协同：系统生物学需要计算科学、数学与统计学协同，完成生物信息的获取、存储、分析、图形化显示和模拟。", "计算数据日益重要：除核酸和蛋白质序列外，功能基因组学与系统生物学推动了对蛋白质-蛋白质相互作用、蛋白质-DNA相互作用和代谢途径等数据的关注。", "代表性数据库：DIP、BIND、MIP、TransFac、SCPD、KEGG、BioCyc等。", "数据挑战：数据规模大、异质性强、噪声高，需要整合与标准化。", "整体分析与模型：通过计算手段进行整体分析，构建数学模型。", "⚠️ 考点/易错点：系统生物学计算依赖计算科学、数学与统计学协同；常用数据库包括DIP、BIND、MIP、TransFac、SCPD、KEGG、BioCyc等，面临数据存储格式与数据保持两大挑战。"], "code": null, "lang": null, "check": {"q": "系统生物学计算中，DIP、BIND、MIP、TransFac、SCPD、KEGG、BioCyc等数据库主要带来哪两个挑战？", "o": ["A. 如何以适当格式系统存储信息，以及如何保持数据更新", "B. 如何减少所有实验数据", "C. 如何避免使用数学模型", "D. 如何只研究单个基因"], "a": "A", "e": "这些数据带来两个挑战：如何以适当格式系统存储信息，以及如何保持数据更新。"}, "cards": [{"front": "系统生物学计算中数据日益重要体现在哪些方面？", "back": "除核酸和蛋白质序列外，功能基因组学与系统生物学推动了对蛋白质-蛋白质相互作用、蛋白质-DNA相互作用和代谢途径等数据的关注，例如DIP、BIND、MIP、TransFac、SCPD、KEGG、BioCyc等数据库。", "mnemonic": "序列之外，互作与通路", "useImg": false}]}, {"i": 7, "sec": "第二节 系统生物学基本技术与方法", "title": "分立电路模型与模型细节选择", "notes": "本页继续第二节内容。与化学反应系统模型不同，另一类模型将遗传网络模拟为分立电路：节点表示不同类别分子的量或水平，有向边表示一个节点对另一个节点的影响；每个节点需一个函数描述所有输入如何决定其水平。节点常表示为二态，如分子存在/缺失、基因开/关。给定初始态，下一状态由当前态和函数计算，网络状态按分立时间序列演化。已有相关模拟软件。该模型的主要批评是：要求即时更新节点数据，但单细胞中分子相互作用并不同步，且二态表示不足以获取网络全部生物学行为。模型细节选择涉及包含哪些基因及基因产物；基因可在转录、翻译及翻译后修饰水平调控，可变剪接使一个基因编码多种mRNA，代谢物等非遗传分子和细胞器区室化也影响网络。完整模型应包含可变剪接、蛋白质修饰及细胞器互作，但细节不易获得，模型参数数量应与可得数据的量和类型一致，避免隐变量过多。", "page": 182, "level": "理解", "img": "assets/img/ch09/p182.jpg", "anim": null, "fig": null, "points": ["分立电路模型：将遗传网络模拟为分立电路，节点表示不同类别分子的量或水平，有向边表示一个节点对另一个节点的影响。", "节点函数：每个节点需一个函数描述所有输入如何决定其水平。", "二态表示：节点常表示为二态，如分子存在/缺失、基因开/关。", "状态演化：给定初始态，下一状态由当前态和函数计算，网络状态按分立时间序列演化。", "主要批评：要求即时更新节点数据，但单细胞中分子相互作用并不同步。", "⚠️ 考点/易错点：分立电路模型：节点表示分子量或水平，有向边表示影响，节点常为二态（存在/缺失、开/关），按分立时间序列演化；主要批评是要求即时更新节点数据且二态表示不足以获取网络全部生物学行为。"], "code": null, "lang": null, "check": {"q": "关于分立电路模型，下列描述正确的是？", "o": ["A. 节点表示不同类别分子的量或水平，有向边表示一个节点对另一个节点的影响", "B. 节点只能表示连续浓度，不能表示二态", "C. 网络状态不能按分立时间序列演化", "D. 该模型不需要函数描述输入如何决定节点水平"], "a": "A", "e": "分立电路模型中，节点表示不同类别分子的量或水平，有向边表示一个节点对另一个节点的影响；节点常表示为二态，网络状态按分立时间序列演化。"}, "cards": [{"front": "分立电路模型如何模拟遗传网络？", "back": "节点表示不同类别分子的量或水平，有向边表示一个节点对另一个节点的影响；每个节点需一个函数描述所有输入如何决定其水平；节点常表示为二态，如分子存在/缺失、基因开/关；给定初始态，下一状态由当前态和函数计算，网络状态按分立时间序列演化。", "mnemonic": "节点二态，函数演化", "useImg": false}]}, {"i": 8, "sec": "第二节 系统生物学基本技术与方法", "title": "基于DBRF方法从稳态表达数据推测基因网络", "notes": "本页属于第三节“基因表达调控网络”。DBRF方法利用稳态基因表达数据推测基因调控网络。设矩阵M的行表示缺失该行基因时其他基因的表达水平，列表示该基因在各种基因缺失试验下的表达水平。通过比较野生型与突变型表达差异，推测交互矩阵IT：行表示调控基因，列表示目标基因，矩阵元素表示激活或抑制关系。若基因a的缺失改变基因b的表达，则推测a调控b，同时可能引入间接调控关系。随后需剪除冗余间接关系：对每个基因，找出是否存在一条以上途径；检查这些途径的调控影响是否一致；若影响相同，则剪除冗余途径。网络模型将基因调控网络描述为包含N个节点a_n及带权重有向边的结构图。节点代表基因，有向边代表调控关系，边权重正负表示激活或抑制。基因a_n的表达水平由非线性Sigmoidal函数g_n决定，表达方程包含最大合成速率R_n、连接权重矩阵z_ij和Sigmoidal函数g(u)=1/2(u/√(z²+1))等，用于描述整体调控。", "page": 183, "level": "掌握", "img": "assets/img/ch09/p183.jpg", "anim": null, "fig": null, "points": ["DBRF方法：利用稳态基因表达数据推测基因调控网络。", "矩阵M：行表示缺失该行基因时其他基因的表达水平，列表示该基因在各种基因缺失试验下的表达水平。", "交互矩阵IT：通过比较野生型与突变型表达差异推测，行表示调控基因，列表示目标基因，矩阵元素表示激活或抑制关系。", "调控推断：若基因a的缺失改变基因b的表达，则推测a调控b，同时可能引入间接调控关系。", "冗余剪除：需剪除冗余间接关系，对每个基因进行后续处理。", "⚠️ 考点/易错点：DBRF法由稳态表达数据推测调控网络时，若基因a缺失改变基因b表达则推测a调控b，但会引入间接调控，必须通过剪除冗余间接关系（检查是否存在一条以上途径）来去除非直接调控。"], "code": null, "lang": null, "check": {"q": "DBRF方法利用稳态基因表达数据推测基因调控网络时，矩阵M的行和列分别表示什么？", "o": ["A. 行表示缺失该行基因时其他基因的表达水平，列表示该基因在各种基因缺失试验下的表达水平", "B. 行表示蛋白质结构，列表示代谢物浓度", "C. 行表示物种，列表示生态系统", "D. 行表示时间点，列表示温度"], "a": "A", "e": "DBRF方法中，矩阵M的行表示缺失该行基因时其他基因的表达水平，列表示该基因在各种基因缺失试验下的表达水平。"}, "cards": [{"front": "DBRF方法如何从稳态表达数据推测基因调控网络？", "back": "设矩阵M的行表示缺失该行基因时其他基因的表达水平，列表示该基因在各种基因缺失试验下的表达水平；通过比较野生型与突变型表达差异，推测交互矩阵IT，行表示调控基因，列表示目标基因，矩阵元素表示激活或抑制关系；若基因a的缺失改变基因b的表达，则推测a调控b，随后需剪除冗余间接关系。", "mnemonic": "缺失看变化，矩阵推调控", "useImg": false}]}, {"i": 9, "sec": "第二节 系统生物学基本技术与方法", "title": "海胆cis-基因调控网络与endol6基因", "notes": "本页属于第三节。反式逻辑定义蛋白质相互作用因子与它们控制的基因或网络中其他转录因子的相互作用；顺式逻辑定义启动子序列之间通过结合状态产生特定基因表达时空模式的精确关系。两类网络均有输入和输出，输入可来自信号转导途径，输出为核RNA浓度，并受RNA加工、可变剪接、蛋白质加工和化学修饰等转录后调控影响。海胆因发育简单、胚胎细胞类型少、卵子量大且可同步受精，成为研究cis和trans基因调控的有力模型。海胆endol6基因具有最完整的cis基因调控系统，在胚胎内皮层表达，随后出现在原肠消化道，最后在中肠密集，前肠和后肠中消失。其2.3 kb基因组区域包含全部控制元件，有34个结合点和13个转录因子，结合点分布于7个DNA区域，包括6个功能调节子A、B、DC、E、F、G和1个基本启动子区。通过报告基因和转基因海胆可测量时空表达输出；调节子G为正调节，F和DC在相邻外胚层中响应表达抑制，A负责整合来自G、F、E、DC和B的正负输入。", "page": 184, "level": "理解", "img": "assets/img/ch09/p184.jpg", "anim": null, "fig": null, "points": ["反式逻辑：定义蛋白质相互作用因子与它们控制的基因或网络中其他转录因子的相互作用。", "顺式逻辑：定义启动子序列之间通过结合状态产生特定基因表达时空模式的精确关系。", "网络输入输出：两类网络均有输入和输出，输入可来自信号转导途径，输出为核RNA浓度。", "转录后调控：输出受RNA加工、可变剪接、蛋白质加工和化学修饰等影响。", "海胆模型：因发育简单、胚胎细胞类型少、卵子量大且可同步受精，成为研究cis和trans基因调控的有力模型。", "⚠️ 考点/易错点：易混点：反式逻辑指蛋白质因子与基因/转录因子的相互作用，顺式逻辑指启动子序列间通过结合状态产生时空表达模式；海胆因发育简单、细胞类型少、卵量大且可同步受精而成为研究cis/trans调控的模型。"], "code": null, "lang": null, "check": {"q": "海胆endol6基因成为研究cis和trans基因调控有力模型的原因不包括？", "o": ["A. 发育简单、胚胎细胞类型少", "B. 卵子量大且可同步受精", "C. 具有最完整的cis基因调控网络之一", "D. 基因组比人类大且复杂"], "a": "D", "e": "海胆因发育简单、胚胎细胞类型少、卵子量大且可同步受精，成为研究cis和trans基因调控的有力模型；endol6基因具有最完整的cis基因调控网络之一。"}, "cards": [{"front": "海胆为何成为研究cis和trans基因调控的有力模型？", "back": "海胆因发育简单、胚胎细胞类型少、卵子量大且可同步受精，成为研究cis和trans基因调控的有力模型。", "mnemonic": "发育简单，卵多同步", "useImg": false}]}, {"i": 10, "sec": "第二节 系统生物学基本技术与方法", "title": "调节子A的布尔逻辑与代谢网络引入", "notes": "本页包含图9-6，展示调节子A的顺式调控逻辑。图中A、B的输出分别用红色和蓝色表示；短化线表示可由布尔式输入调节的相互作用，细实线表示标量，粗实线表示时间依赖的定量输入；箭头表示正效应，垂直箭头表示负效应。例如，CY和CB1相互作用激发调节子A时空控制元件U1的输出。该图说明海胆endol6调控网络如何通过多个转录因子结合位点整合正负输入，形成精确的时空表达模式。随后进入第四节“代谢网络”，以酵母半乳糖利用系统为例，采用系统方法探索代谢机制。与海胆顺式调控序列控制基因表达不同，该网络由基因和反式相互作用的基因产物组成。酵母半乳糖利用系统至少包含9个基因，其中GAL1、GAL5、GAL7、GAL10编码催化半乳糖转化为葡萄糖-6-磷酸的酶，GAL2编码转运分子；GAL3、GAL4、GAL80、GAL6等转录因子参与开/关调控。有半乳糖时系统开启，缺少时关闭。", "page": 185, "level": "理解", "img": "assets/img/ch09/p185.jpg", "anim": null, "fig": "图9-6为调节子A的顺式调控逻辑图，用红蓝两色区分A、B输出，以不同线型表示布尔调节、标量和时间依赖的定量输入，箭头和垂直箭头分别表示正、负效应。图中示例显示CY和CB1共同激发U1输出，说明海胆endol6网络如何整合多转录因子输入形成时空表达模式。", "points": ["图9-6展示调节子A的顺式调控逻辑，红色和蓝色分别表示A、B的输出。", "短化线表示可由布尔式输入调节的相互作用，细实线表示标量，粗实线表示时间依赖的定量输入。", "箭头表示正效应，垂直箭头表示负效应；例如CY和CB1相互作用激发调节子A时空控制元件U1的输出。", "海胆endol6调控网络通过多个转录因子结合位点整合正负输入，形成精确的时空表达模式。", "本页随后进入第四节“代谢网络”，以酵母为例展开。", "⚠️ 考点/易错点：图9-6中符号含义易考：短化线=布尔式输入调节，细实线=标量，粗实线=时间依赖的定量输入，箭头=正效应，垂直箭头=负效应；该页还标志由基因调控网络转入第四节代谢网络。"], "code": null, "lang": null, "check": {"q": "图9-6展示调节子A的顺式调控逻辑时，箭头和垂直箭头分别表示什么？", "o": ["A. 箭头表示正效应，垂直箭头表示负效应", "B. 箭头表示负效应，垂直箭头表示正效应", "C. 两者都表示正效应", "D. 两者都表示无效应"], "a": "A", "e": "图中箭头表示正效应，垂直箭头表示负效应；短化线表示可由布尔式输入调节的相互作用。"}, "cards": [{"front": "图9-6中调节子A的顺式调控逻辑用什么颜色和线型表示？", "back": "红色和蓝色分别表示A、B的输出；短化线表示可由布尔式输入调节的相互作用，细实线表示标量，粗实线表示时间依赖的定量输入；箭头表示正效应，垂直箭头表示负效应。", "mnemonic": "红A蓝B，短线布尔，细标量，粗定量，箭头正，垂箭负。", "useImg": false}]}, {"i": 11, "sec": "第二节 系统生物学基本技术与方法", "title": "酵母半乳糖利用模型与遗传扰动网络整合", "notes": "本页属于第四节“代谢网络”。图9-7展示酵母半乳糖利用模型：酵母通过GAL2转运蛋白及GAL1、GAL7、GAL10、GAL5产生的酶，将半乳糖逐步代谢为葡萄糖-6-磷酸；这些基因主要在转录水平受GAL3、GAL4、GAL80等调控，GAL6通过类似GAL80的方式抑制GAL酶产生，点画线表示后加修正。为确定分子相互作用是否足以解释GAL通路扰动后的基因表达变化，构建了9个遗传扰动酵母株，每个删除一个不同基因，并与野生型一起在含2%半乳糖条件下培养。进一步关注3026个物理相互作用，定义分子相互作用网络模型：节点表示基因，有向线段表示第一个基因编码的蛋白质通过DNA结合影响第二个基因的转录，无向线段表示蛋白质间物理相互作用。将每个扰动下的表达数据可视化加入网络，例如图9-8(a)显示半乳糖存在时gal4Δ删除突变体的表达变化，图9-8(b)显示氨基酸生物代谢相关网络，从而整合物理相互作用与表达变化。", "page": 186, "level": "掌握", "img": "assets/img/ch09/p186.jpg", "anim": null, "fig": "图9-7为酵母半乳糖利用模型示意图，显示半乳糖经GAL2转运及GAL1、GAL7、GAL10、GAL5酶促反应逐步转化为葡萄糖-6-磷酸。图中还标出GAL3、GAL4、GAL80等转录调控因子及GAL6的类似GAL80抑制方式，点画线表示后加修正。", "points": ["图9-7展示酵母半乳糖利用模型：GAL2转运蛋白及GAL1、GAL7、GAL10、GAL5产生的酶将半乳糖逐步代谢为葡萄糖-6-磷酸。", "这些基因主要在转录水平受GAL3、GAL4、GAL80等调控，GAL6通过类似GAL80的方式抑制GAL酶产生。", "点画线表示后加修正，用于完善模型。", "为确定分子相互作用是否足以解释GAL通路扰动后的基因表达变化，构建了9个遗传扰动酵母株，每个删除一个基因。", "⚠️ 考点/易错点：酵母半乳糖利用模型的关键基因功能易混：GAL2为转运蛋白，GAL1/GAL7/GAL10/GAL5为代谢酶，GAL3/GAL4/GAL80在转录水平调控，GAL6类似GAL80抑制GAL酶产生。"], "code": null, "lang": null, "check": {"q": "酵母半乳糖利用模型中，GAL2转运蛋白及GAL1、GAL7、GAL10、GAL5产生的酶将半乳糖逐步代谢为？", "o": ["A. 葡萄糖-6-磷酸", "B. 丙酮酸", "C. 脂肪酸", "D. 氨基酸"], "a": "A", "e": "酵母通过GAL2转运蛋白及GAL1、GAL7、GAL10、GAL5产生的酶，将半乳糖逐步代谢为葡萄糖-6-磷酸。"}, "cards": [{"front": "酵母半乳糖利用模型中，半乳糖如何逐步代谢为葡萄糖-6-磷酸？受哪些基因调控？", "back": "酵母通过GAL2转运蛋白及GAL1、GAL7、GAL10、GAL5产生的酶，将半乳糖逐步代谢为葡萄糖-6-磷酸；这些基因主要在转录水平受GAL3、GAL4、GAL80等调控，GAL6通过类似GAL80的方式抑制GAL酶产生。", "mnemonic": "GAL2转运，GAL1/7/10/5酶促，GAL3/4/80调控，GAL6抑制。", "useImg": false}]}, {"i": 12, "sec": "第四节 代谢网络", "title": "GAL网络扰动观察与模型预测的比较", "notes": "本页属于第四节代谢网络。核心是把分子相互作用网络用于解释20种扰动下GAL基因表达响应，并比较观察值与预测值。图中节点灰度表示对应基因mRNA表达变化；图9-8(b)进一步叠加蛋白质丰度信息，聚焦氨基酸生物合成相关网络区，通过比较同一节点的mRNA与蛋白质表达响应，判断二者是否相关。网络模型只能作粗略预测：若蛋白质A与基因B的DNA有相互作用，则A表达变化可预测B表达变化；若A还与蛋白质C互作，则C变化也可通过A影响B。但网络通常不编码激活/抑制方向，也不说明多个相互作用如何整合，更不能直接说明蛋白质复合物形成或翻译后修饰。因此需要整合经典遗传学与生物化学知识，例如Gal4p是强转录激活子、Gal80p结合Gal4p抑制其功能，并挖掘文献补充相互作用的符号与机制。图9-9比较20种扰动下GAL表达响应的观察与预测，观察响应更复杂，但许多性质上一致，说明模型可修正并增强预测能力。", "page": 187, "level": "掌握", "img": "assets/img/ch09/p187.jpg", "anim": null, "fig": "图9-8(a)以节点灰度表示GAL基因mRNA表达变化，比较20种扰动下的观察值与预测值；图9-8(b)叠加蛋白质丰度信息，聚焦氨基酸生物合成相关网络区，比较同一节点的mRNA与蛋白质表达响应是否相关。", "points": ["核心是把分子相互作用网络用于解释20种扰动下GAL基因表达响应，并比较观察值与预测值。", "图中节点灰度表示对应基因mRNA表达变化。", "图9-8(b)进一步叠加蛋白质丰度信息，聚焦氨基酸生物合成相关网络区，通过比较同一节点的mRNA与蛋白质表达响应，判断二者是否相关。", "网络模型只能作粗略预测：若蛋白质A与基因B的DNA有相互作用，则A表达变化可预测B表达变化；若A还与蛋白质C互作，则预测更复杂。", "⚠️ 考点/易错点：网络模型只能作粗略预测：若蛋白质A与基因B的DNA互作则A表达变化可预测B变化，若A还与C互作则C也可通过A影响B；但网络通常不编码代谢物等间接效应，故观察值与预测值会有差异。"], "code": null, "lang": null, "check": {"q": "GAL网络扰动观察与模型预测比较中，网络模型只能作粗略预测的主要原因是什么？", "o": ["A. 网络通常不编码动力学参数和调控强度", "B. 网络完全没有节点", "C. 网络不能表示相互作用", "D. 网络只能表示代谢物"], "a": "A", "e": "网络模型只能作粗略预测，因为网络通常不编码动力学参数和调控强度等信息。"}, "cards": [{"front": "GAL网络扰动观察与模型预测比较的核心是什么？网络模型预测有何局限？", "back": "核心是把分子相互作用网络用于解释20种扰动下GAL基因表达响应，并比较观察值与预测值。图中节点灰度表示mRNA表达变化，图9-8(b)叠加蛋白质丰度信息。网络模型只能作粗略预测：若蛋白质A与基因B的DNA有相互作用，则A表达变化可预测B表达变化；若A还与蛋白质C互作，则预测更复杂。", "mnemonic": "20扰动，灰度mRNA，叠加蛋白，粗略预测。", "useImg": false}]}, {"i": 13, "sec": "第四节 代谢网络", "title": "GAL通路系统生物学修正与细菌化学趋向导论", "notes": "本页前半属于第四节代谢网络，后半进入第五节信号转导途径。为检验代谢物Gal-1-P是否导致gal10突变中GAL基因表达变化，作者在半乳糖利用条件下构建gal1 gal10双删除株。GAL10删除阻断Gal-1-P转化，GAL1删除阻断半乳糖利用通路更上游步骤，使Gal-1-P水平大幅降低。若代谢物是表达变化原因，则gal10单突变中的GAL表达变化应在gal1 gal10双突变中消失。微阵列检测双删除株表达谱证实了这一点，支持修正模型。这说明半乳糖利用的系统生物学方法能揭示通路如何调控以及如何与酵母其他信息通路联系，并可推广到其他生物系统乃至多细胞生物细胞互作网络。随后进入第五节信号转导途径，以细菌化学趋向为鲁棒信号转导模型。化学趋向是细菌移向或离开化学源的过程，研究历史超过120年。细菌通过偏向随机行走、向前游动和随机再定位在化学梯度中移动；游动时鞭毛马达逆时针转动，感受吸引或排斥，增加吸引或减少排斥导致沿确定方向持续游动。图9-10示意化学趋向分子机制，涉及甲基接受化学趋向蛋白等。", "page": 188, "level": "掌握", "img": "assets/img/ch09/p188.jpg", "anim": null, "fig": null, "points": ["为检验代谢物Gal-1-P是否导致gal10突变中GAL基因表达变化，在半乳糖利用条件下构建gal1 gal10双删除株。", "GAL10删除阻断Gal-1-P转化，GAL1删除阻断半乳糖利用通路更上游步骤，使Gal-1-P水平大幅降低。", "若代谢物是表达变化原因，则gal10单突变中的GAL表达变化应在gal1 gal10双突变中消失。", "微阵列检测用于验证该假设。", "本页后半进入第五节信号转导途径，以细菌化学趋向导论。", "⚠️ 考点/易错点：检验代谢物Gal-1-P是否为gal10突变中GAL表达变化原因的经典逻辑：构建gal1 gal10双删除株使Gal-1-P大幅降低，若gal10单突变中的表达变化在双突变中消失，则支持代谢物因果作用（修正模型）。"], "code": null, "lang": null, "check": {"q": "为检验代谢物Gal-1-P是否导致gal10突变中GAL基因表达变化，作者构建了什么菌株？", "o": ["A. gal1 gal10双删除株", "B. 野生型过表达株", "C. 仅gal1单删除株", "D. 仅gal10单删除株"], "a": "A", "e": "作者构建gal1 gal10双删除株，若代谢物是表达变化原因，则gal10单突变中的GAL表达变化应在gal1 gal10双突变中消失。"}, "cards": [{"front": "如何检验代谢物Gal-1-P是否导致gal10突变中GAL基因表达变化？", "back": "在半乳糖利用条件下构建gal1 gal10双删除株。GAL10删除阻断Gal-1-P转化，GAL1删除阻断半乳糖利用通路更上游步骤，使Gal-1-P水平大幅降低。若代谢物是表达变化原因，则gal10单突变中的GAL表达变化应在gal1 gal10双突变中消失。用微阵列检测验证。", "mnemonic": "双删gal1 gal10，降Gal-1-P，看变化是否消失。", "useImg": false}]}, {"i": 14, "sec": "第四节 代谢网络", "title": "化学趋向的鲁棒适应与积分负反馈", "notes": "本页属于第五节信号转导途径。MCP共有5个跨膜受体，含多个甲基化位点，其修饰状态控制信号转导；该信号网络调节鞭毛马达输出，也调节对吸引或排斥物浓度变化的敏感性。Spiro等用质量作用动力学方程模拟不同配体占据、磷酸化和甲基化状态之间化学趋向分子的转化，概括了对吸引梯度、步幅增加和饱和度的响应，从而研究系统性质而非单个成分。化学趋向网络的重要系统性质是鲁棒适应：系统输出对输入或生化参数的个别选择不敏感；鲁棒适应指输出对输入变化的响应不依赖整体输入值。大肠杆菌通过改变翻动频率响应吸引浓度变化，但均一引诱物解在不同浓度下产生相同翻动频率。分子机制上，受体复合物由MCP、CheA和CheW组成，磷酸化响应调节子CheY；磷酸化CheY结合鞭毛马达产生顺时针旋转。受体复合物活性受甲基化调节：CheR甲基化增强活性，CheB去甲基化降低活性。细菌趋向性表现完全适应：诱导物持续作用时输出先短暂升高，随后适应并回到刺激前水平，且在大范围诱导物浓度下均如此。Barkai和Leibler模拟显示化学适应鲁棒性。", "page": 189, "level": "掌握", "img": "assets/img/ch09/p189.jpg", "anim": null, "fig": null, "points": ["MCP共有5个跨膜受体，含多个甲基化位点，其修饰状态控制信号转导。", "该信号网络调节鞭毛马达输出，也调节对吸引或排斥物浓度变化的敏感性。", "Spiro等用质量作用动力学方程模拟不同配体占据、磷酸化和甲基化状态之间化学趋向分子的转化。", "概括了对吸引梯度、步幅增加和饱和度的响应，从而研究系统性质而非单个成分。", "化学趋向网络的重要系统性质是鲁棒适应：系统输出对输入或生化参数的个别选择不敏感。", "⚠️ 考点/易错点：化学趋向的核心系统性质是鲁棒适应：输出对输入或生化参数的个别选择不敏感；MCP受体甲基化状态控制信号转导，Spiro等用质量作用动力学模拟配体占据、磷酸化和甲基化状态间的转化。"], "code": null, "lang": null, "check": {"q": "化学趋向网络中，鲁棒适应指的是？", "o": ["A. 系统输出对输入或生化参数的个别选择不敏感", "B. 系统输出完全随机", "C. 系统不能适应环境变化", "D. 系统只对单一刺激响应"], "a": "A", "e": "鲁棒适应指系统输出对输入或生化参数的个别选择不敏感，是化学趋向网络的重要系统性质。"}, "cards": [{"front": "化学趋向网络的重要系统性质是什么？MCP受体有何特点？", "back": "重要系统性质是鲁棒适应：系统输出对输入或生化参数的个别选择不敏感。MCP共有5个跨膜受体，含多个甲基化位点，其修饰状态控制信号转导；该信号网络调节鞭毛马达输出，也调节对吸引或排斥物浓度变化的敏感性。", "mnemonic": "鲁棒适应，MCP五跨膜，甲基化控信号。", "useImg": false}]}, {"i": 15, "sec": "第四节 代谢网络", "title": "积分控制方程、正向工程与三蛋白振荡网络", "notes": "本页属于第五节信号转导途径。Barkai-Leibler模型用变量描述受体复合物甲基化状态，设z为甲基化状态，其变化等于甲基化速率r减去CheB去甲基化速率。假设CheB只对被激活的受体复合物去甲基化，则去甲基化速率写成受体活性水平A的函数，得到微分方程 dz/dt = r - bA = -b(A - r/b) = -b y，其中误差变量y趋于0。该式说明系统可实现积分负反馈控制，将趋向性信号转导网络添加到积分控制结构图中，在CheB只作用于激活受体复合物的假设下得到积分控制式。图9-11给出积分负反馈控制与细菌趋化性的方块图。随后讨论生物学网络的正向工程：此前例子是构建自然生物系统的力学模型，属反向工程，即改变模型适应生物系统；正向工程则是改变生物系统检验模型，合成生物学即正向工程。Elowitz等构建大肠杆菌基因调控系统，图9-12为三蛋白振荡网络：抑制子质粒编码三个蛋白质，每个与外源启动子融合，在闭合负反馈环中一个蛋白质抑制下一个蛋白质转录，即TetR抑制cI，cI抑制LacI，LacI抑制TetR；报告质粒用于跟踪TetR浓度振荡。", "page": 190, "level": "掌握", "img": "assets/img/ch09/p190.jpg", "anim": null, "fig": null, "points": ["Barkai-Leibler模型用变量描述受体复合物甲基化状态，设z为甲基化状态。", "其变化等于甲基化速率r减去CheB去甲基化速率。", "假设CheB只对被激活的受体复合物去甲基化，则去甲基化速率写成受体活性水平A的函数。", "得到微分方程 dz/dt = r - bA = -b(A - r/b) = -b y，其中误差变量y趋于0。", "该式说明系统可实现积分负反馈控制，将趋向性信号转导与正向工程及三蛋白振荡网络联系起来。", "⚠️ 考点/易错点：Barkai-Leibler模型易考公式：dz/dt = r - bA = -b(A - r/b) = -b y，误差变量y趋于0，说明系统实现积分负反馈控制；需理解CheB只对被激活受体复合物去甲基化这一假设。"], "code": null, "lang": null, "check": {"q": "Barkai-Leibler模型中，微分方程 dz/dt = r - bA = -b(A - r/b) = -b y 说明系统可实现什么控制？", "o": ["A. 积分负反馈控制", "B. 正反馈放大", "C. 前馈抑制", "D. 随机噪声控制"], "a": "A", "e": "该式说明系统可实现积分负反馈控制，误差变量y趋于0。"}, "cards": [{"front": "Barkai-Leibler模型中甲基化状态z的微分方程是什么？说明什么控制机制？", "back": "dz/dt = r - bA = -b(A - r/b) = -b y，其中误差变量y趋于0。该式说明系统可实现积分负反馈控制，将趋向性信号转导与正向工程及三蛋白振荡网络联系起来。", "mnemonic": "dz/dt = r - bA = -b y，积分负反馈。", "useImg": false}]}, {"i": 16, "sec": "第四节 代谢网络", "title": "光传导单光子响应与钙介导反馈模块", "notes": "本页属于第五节信号转导途径。讨论光传导中单光子响应的鲁棒性。视网膜中杆状和锥状光感受细胞感光，将信息传至视皮层。视感细胞几何结构特殊，外节片段由许多膜盘组成，装载光传导信号级联成分。杆状光感受细胞感受一个单光子时产生固定响应，Baylor等发现单光子响应有惊人重现性。图9-13为光传导途径简图：(a)将路径分成模块的示意图；(b)将路径示意图换成数学模型。单光子响应由受体激活与关闭控制。单个受体由单光子激活，激活的视紫红质R*被视紫红质激酶GRK磷酸化，随后与抑制蛋白结合而关闭。R*激活多个G蛋白，G蛋白再刺激cGMP磷酸二酯酶PDE。激活的PDE*降解第二信使cGMP，使其浓度降低，导致cGMP门控通道关闭，流量变化。两个钙反馈循环值得注意：钙经cGMP通道进入细胞，因此胞内钙浓度是流量j的函数。一个循环中，鸟苷酸环化酶GC受钙结合蛋白GCAP调节；另一个循环中，视紫红质激酶受恢复蛋白调节。建模时，给定时刻R*水平用概率函数描述，G蛋白和PDE分子由单个R*激活，扩增后下一物种浓度可用常微分方程ODE表示，最后通过线性变换函数近似某些方程。", "page": 191, "level": "掌握", "img": "assets/img/ch09/p191.jpg", "anim": null, "fig": "图9-13为光传导途径简图，(a)将路径分成模块的示意图，(b)将路径示意图换成数学模型。单光子响应由受体激活与关闭控制，单个受体由多个生化步骤调节，体现光传导的鲁棒性。", "points": ["讨论光传导中单光子响应的鲁棒性。", "视网膜中杆状和锥状光感受细胞感光，将信息传至视皮层。", "视感细胞几何结构特殊，外节片段由许多膜盘组成，装载光传导信号级联成分。", "杆状光感受细胞感受一个单光子时产生固定响应，Baylor等发现单光子响应有惊人重现性。", "图9-13为光传导途径简图：(a)将路径分成模块的示意图；(b)将路径示意图换成数学模型。", "⚠️ 考点/易错点：光传导单光子响应的重现性由受体激活与关闭共同控制，易考Baylor等发现单光子响应具有惊人重现性，以及图9-13将路径分为模块并建立数学模型。"], "code": null, "lang": null, "check": {"q": "光传导中，钙介导的GCAP对GC的调节可看作什么？", "o": ["A. 滞后补偿器", "B. 积分控制器", "C. 正反馈放大器", "D. 随机开关"], "a": "A", "e": "只有滞后补偿器系统能与实际数据符合，因此钙介导的GCAP对GC的调节可看作滞后补偿器，增强单光子响应鲁棒性。"}, "cards": [{"front": "光传导中单光子响应的鲁棒性有何实验发现？图9-13展示什么？", "back": "杆状光感受细胞感受一个单光子时产生固定响应，Baylor等发现单光子响应有惊人重现性。图9-13为光传导途径简图：(a)将路径分成模块的示意图；(b)将路径示意图换成数学模型。单光子响应由受体激活与关闭控制。", "mnemonic": "单光子固定响应，图9-13分模块与数学模型。", "useImg": false}]}, {"i": 17, "sec": "第四节 代谢网络", "title": "动态平衡、双相响应调节与正反馈偶联", "notes": "本页属于第五节信号转导途径。前半总结光传导：积分控制器响应上升很快但最终回到零，只有滞后补偿器系统能与实际数据符合，因此钙介导的GCAP对GC的调节可看作滞后补偿器，增强单光子响应鲁棒性。随后讨论动态平衡和信号转导中的双相响应调节与正反馈。从细菌到人都需保持内部环境不变，并对引起动态平衡瞬态变化的外部信号足够灵敏。常见现象是信号转导途径中分子浓度维持在接收信号前的最优值。动态平衡分两类：一是某变量如调节蛋白浓度因外部扰动瞬间变化但仍维持一定水平，称稳态，该调节方式为自动调节；二是外部参数影响变量时，通过补偿使变量最终返回稳定状态，称动态平衡适应。通常认为动态平衡适应系统稳定或自动调节，自动调节是基本特征。双相调节与正反馈结合的自动调节机制为：第一种分子激活促进第二种分子激活；第二种分子在活性低时促进第一种分子激活，活性高时抑制第一种分子激活。假设两个变量x(t)和y(t)，表示为 dx/dt = f(S,x,y)，dy/dt = g(x,y)，S为外部参数，影响x性质。若y对x只有促进作用，将x固定为x0，则第一式最终满足f(S,x0,y)=0，对应所有y值得到双相曲线y=f(S,x0)。", "page": 192, "level": "掌握", "img": "assets/img/ch09/p192.jpg", "anim": null, "fig": null, "points": ["前半总结光传导：积分控制器响应上升很快但最终回到零，只有滞后补偿器系统能与实际数据符合。", "因此钙介导的GCAP对GC的调节可看作滞后补偿器，增强单光子响应鲁棒性。", "随后讨论动态平衡和信号转导中的双相响应调节与正反馈。", "从细菌到人都需保持内部环境不变，并对引起动态平衡瞬态变化的外部信号足够灵敏。", "常见现象是信号转导途径中分子浓度维持在接收信号前的最优值；动态平衡分两类。", "⚠️ 考点/易错点：钙介导的GCAP对GC的调节可看作滞后补偿器，而非积分控制器；积分控制器响应虽快但最终回到零，只有滞后补偿器系统能与实际数据符合，这是单光子响应鲁棒性的关键。"], "code": null, "lang": null, "check": {"q": "关于动态平衡和信号转导中的双相响应调节，下列说法正确的是？", "o": ["A. 动态平衡指某变量因外部扰动瞬间变化但仍维持在一定范围", "B. 双相响应只能单调增加", "C. 正反馈不会影响双相调节", "D. 动态平衡与信号转导无关"], "a": "A", "e": "动态平衡分两类，其中一类是某变量如调节蛋白浓度因外部扰动瞬间变化但仍维持在一定范围；双相响应曲线上升部分可使响应外部扰动的z值出现峰值。"}, "cards": [{"front": "光传导中哪种控制器系统与实际数据符合？动态平衡分哪两类？", "back": "只有滞后补偿器系统能与实际数据符合，因此钙介导的GCAP对GC的调节可看作滞后补偿器，增强单光子响应鲁棒性。动态平衡分两类：一是某变量维持在最优值附近，二是双相响应调节与正反馈。", "mnemonic": "滞后补偿器，钙介导GCAP；动态平衡两类。", "useImg": false}]}, {"i": 18, "sec": "第五节 信号转导途径", "title": "双相调节-正反馈偶联与TATA框结合蛋白调控", "notes": "本页承接双相响应曲线，说明外部参数S变化时响应函数f(S,z)的两种行为：在活动芽中沿零渐变群上升方向最大值增大，沿下降方向最大值减小；静止状态从(0,0)附近低值到高值存在关于S的阈值函数。双相响应曲线上升部分可使响应外部扰动的z值出现峰值。随后以TATA框和TBP为例说明双相调节-正反馈偶联的生物学应用。TATA框位于真核高表达基因启动子转录起始位点上游25–35 bp，是TATA结合蛋白TBP的结合位点。TBP以单体形式结合TATA框及其他调控因子，同时可自身低聚形成四聚体和八聚体；低聚可能阻止TBP与DNA结合，因为负责DNA结合的TBP表面也参与低聚。TBP在转录起始中重要，其表达受紧密调控。TBP启动子含一个TATA框和两个控制元件，TATA框为基础转录必需，两个控制元件结合TBP启动结合因子TBFP，其中上游一个为高亲和力结合位点。", "page": 193, "level": "理解", "img": "assets/img/ch09/p193.jpg", "anim": null, "fig": null, "points": ["承接双相响应曲线，说明外部参数S变化时响应函数f(S,z)的两种行为。", "在活动芽中沿零渐变群上升方向最大值增大，沿下降方向最大值减小。", "静止状态从(0,0)附近低值到高值存在关于S的阈值函数。", "双相响应曲线上升部分可使响应外部扰动的z值出现峰值。", "以TATA框和TBP为例说明双相调节-正反馈偶联的生物学应用：TATA框位于真核高表达基因启动子转录起始位点上游25–35 bp，是TATA结合蛋白TBP的结合位点。", "⚠️ 考点/易错点：双相响应曲线中，沿零渐变群上升方向最大值增大、下降方向最大值减小；TATA框位于真核高表达基因启动子转录起始位点上游25–35 bp，是TBP结合位点，易考位置与功能。"], "code": null, "lang": null, "check": {"q": "TATA框位于真核高表达基因启动子转录起始位点上游多少bp？", "o": ["A. 25–35 bp", "B. 100–200 bp", "C. 500–1000 bp", "D. 1–5 bp"], "a": "A", "e": "TATA框位于真核高表达基因启动子转录起始位点上游25–35 bp，是TATA结合蛋白TBP的结合位点。"}, "cards": [{"front": "双相响应曲线中外部参数S变化时响应函数f(S,z)有哪两种行为？TATA框和TBP有何关系？", "back": "在活动芽中沿零渐变群上升方向最大值增大，沿下降方向最大值减小；静止状态从(0,0)附近低值到高值存在关于S的阈值函数。双相响应曲线上升部分可使响应外部扰动的z值出现峰值。TATA框位于真核高表达基因启动子转录起始位点上游25–35 bp，是TATA结合蛋白TBP的结合位点。", "mnemonic": "活动芽升降，静止阈值；TATA框上游25–35 bp，TBP结合。", "useImg": false}]}, {"i": 19, "sec": "第五节 信号转导途径", "title": "TBP-TBFP双相调节与Ca2+振荡的反馈解释", "notes": "本页以图9-18展示TBP浓度与TBFP浓度的活性相关，说明高亲和力激活和低亲和力抑制位点共存时产生双相调节。随后讨论IP3受体开放概率受IP3浓度和ATP调节：增加IP3使最优值位置正移并增大开放概率最大值；IP3变构降低Ca2+对抑制位点亲和力，但保持对激活位点亲和力不变；降低Ca2+对激活位点亲和力可使最优值位置负移，从而增加ATP浓度。低或高IP3时Ca2+稳定且分级相关，中间IP3范围可导致Ca2+上下波动。图9-19用反馈曲线非单调性解释：负反馈区域稳定状态失稳并可能振荡，正反馈区域状态稳定且响应分级。图中实线为输入对输出的最优控制，修饰成分如IP3或MAPKKK活性从a到b再到c；反馈曲线包括MAPK调控的单调正反馈和Ca2+调控的非单调反馈；交点1、2、3、1、3稳定，2不稳定，2处不稳定可引起振动。", "page": 194, "level": "理解", "img": "assets/img/ch09/p194.jpg", "anim": null, "fig": "图9-18展示TBP浓度与TBFP浓度的活性相关曲线，呈双相调节特征，说明高亲和力激活位点和低亲和力抑制位点共存时，随TBP浓度变化活性先升后降。该图用于解释TBP-TBFP双相调节机制。", "points": ["图9-18展示TBP浓度与TBFP浓度的活性相关，说明高亲和力激活和低亲和力抑制位点共存时产生双相调节。", "讨论IP3受体开放概率受IP3浓度和ATP调节。", "增加IP3使最优值位置正移并增大开放概率最大值。", "IP3变构降低Ca2+对抑制位点亲和力，但保持对激活位点亲和力不变。", "降低Ca2+对激活位点亲和力可使最优值位置负移，从而增加ATP浓度；低或高IP3时Ca2+稳定且分级相关，中间IP3范围可产生Ca2+振荡。", "⚠️ 考点/易错点：TBP-TBFP双相调节源于高亲和力激活位点和低亲和力抑制位点共存；IP3受体开放概率受IP3和ATP调节，低或高IP3时Ca2+稳定且分级相关，中间IP3范围才导致Ca2+上下波动。"], "code": null, "lang": null, "check": {"q": "关于IP3受体开放概率受IP3浓度和ATP调节，下列描述正确的是？", "o": ["A. 增加IP3使最优值位置正移并增大开放概率最大值", "B. 增加IP3使最优值位置负移", "C. IP3不影响Ca2+对抑制位点亲和力", "D. 低或高IP3时Ca2+必然剧烈振荡"], "a": "A", "e": "增加IP3使最优值位置正移并增大开放概率最大值；IP3变构降低Ca2+对抑制位点亲和力，但保持对激活位点亲和力不变。"}, "cards": [{"front": "图9-18展示什么？IP3如何调节IP3受体开放概率并影响Ca2+振荡？", "back": "图9-18展示TBP浓度与TBFP浓度的活性相关，说明高亲和力激活和低亲和力抑制位点共存时产生双相调节。增加IP3使最优值位置正移并增大开放概率最大值；IP3变构降低Ca2+对抑制位点亲和力，但保持对激活位点亲和力不变；降低Ca2+对激活位点亲和力可使最优值位置负移，从而增加ATP浓度。低或高IP3时Ca2+稳定且分级相关，中间IP3范围可产生Ca2+振荡。", "mnemonic": "TBP-TBFP双相；IP3正移增最大，变构降抑制，中间IP3振荡。", "useImg": false}]}, {"i": 20, "sec": "第五节 信号转导途径", "title": "MAPK级联的双相调节及蛋白质相互作用网络引论", "notes": "本页先讲MAPK浓度调节。MAPK级联由MAPKKK、MAPKK、MAPK三个顺序激酶组成；MAPKKK双磷酸化MAPKK的苏氨酸和丝氨酸残基而激活MAPKK，MAPKK再双磷酸化MAPK的酪氨酸和苏氨酸残基而激活MAPK。两个磷酸化反应通过激酶与底物完全分裂而分开。理论和实验表明，MAPKK和MAPK活性分布导致信号转导和输出与这些激酶浓度呈双相相关；当酶底物浓度高时，激活酶饱和，未激活的MAPK不能使第二个酶底物磷酸化。三个例子说明双相调节-正反馈偶联可产生自动调控和信号响应机制，可替代简单负反馈并改善调节：双相响应最大值使稳定状态激活有上限，而简单负反馈响应几乎可无穷大；该偶联对维持适当活性值至关重要，并能产生峰值响应或可刺激性，常见于Ca2+调控细胞。随后进入第六节蛋白质-蛋白质相互作用网络，指出研究从单个分子转向分子间相互作用及复杂网络，高通量蛋白质组技术使相互作用数据指数增长。", "page": 195, "level": "掌握", "img": "assets/img/ch09/p195.jpg", "anim": null, "fig": null, "points": ["MAPK级联由MAPKKK、MAPKK、MAPK三个顺序激酶组成，逐级磷酸化传递信号。", "MAPKKK双磷酸化MAPKK的苏氨酸和丝氨酸残基而激活MAPKK；MAPKK再双磷酸化MAPK的酪氨酸和苏氨酸残基而激活MAPK。", "两个磷酸化反应通过激酶与底物完全分裂而分开，保证信号传递的特异性。", "理论和实验表明，MAPKK和MAPK活性分布导致信号转导和输出与这些激酶浓度呈双相相关。", "当酶底物浓度高时，激活酶饱和，未激活的MAPK等可能影响信号输出。", "⚠️ 考点/易错点：MAPK级联由MAPKKK、MAPKK、MAPK三个顺序激酶组成，MAPKKK双磷酸化MAPKK的苏氨酸和丝氨酸残基，MAPKK再双磷酸化MAPK的酪氨酸和苏氨酸残基；酶底物浓度高时激活酶饱和，导致信号输出与激酶浓度呈双相相关。"], "code": null, "lang": null, "check": {"q": "MAPK级联中，MAPKKK激活MAPKK的方式是？", "o": ["A. 双磷酸化MAPKK的苏氨酸和丝氨酸残基", "B. 单磷酸化MAPKK的酪氨酸残基", "C. 去磷酸化MAPKK", "D. 直接降解MAPKK"], "a": "A", "e": "MAPKKK双磷酸化MAPKK的苏氨酸和丝氨酸残基而激活MAPKK，MAPKK再双磷酸化MAPK的酪氨酸和苏氨酸残基而激活MAPK。"}, "cards": [{"front": "MAPK级联由哪三个顺序激酶组成？MAPKKK和MAPKK分别磷酸化哪些残基？", "back": "MAPK级联由MAPKKK、MAPKK、MAPK三个顺序激酶组成。MAPKKK双磷酸化MAPKK的苏氨酸和丝氨酸残基而激活MAPKK；MAPKK再双磷酸化MAPK的酪氨酸和苏氨酸残基而激活MAPK。", "mnemonic": "K-K-K，苏丝再酪苏", "useImg": false}]}, {"i": 21, "sec": "第五节 信号转导途径", "title": "蛋白质相互作用网络的基本概念、性质与网络表示", "notes": "本页介绍蛋白质相互作用网络的基本概念及性质。图9-20说明网络由一组元素（节点）和一组二元关系（边）组成，节点可表示分子、基因等，边可表示分子相互作用、遗传相互作用或其他类型相互作用；网络可表现为通路、组装、近邻、基因组、层级树等。蛋白质参与的相互作用越多，对细胞生存越重要。无标度拓扑组织增加系统稳健性，使网络在部分组件故障、环境改变或外来攻击时尽量保持稳定。由于绝大多数节点连接度低，一般受影响的常是非致命节点，除非扰动过大或高度节点/重要节点被破坏；Hub节点破坏可能导致网络崩塌，因此Hub进化可能更慢。图9-21对比指数式网络和无标度网络：指数网络连接度分布近似指数衰减，无标度网络存在少数高度Hub节点，连接度服从幂律分布。", "page": 196, "level": "掌握", "img": "assets/img/ch09/p196.jpg", "anim": null, "fig": "图9-20说明网络由节点和边组成，节点可表示分子、基因等，边可表示分子相互作用、遗传相互作用等。网络可表现为通路、组装、近邻、基因组、层级树等。", "points": ["蛋白质相互作用网络由一组元素（节点）和一组二元关系（边）组成。", "节点可表示分子、基因等，边可表示分子相互作用、遗传相互作用或其他类型相互作用。", "网络可表现为通路、组装、近邻、基因组、层级树等多种形式。", "蛋白质参与的相互作用越多，对细胞生存越重要。", "无标度拓扑组织增加系统稳健性，使网络在部分组件故障、环境改变或外来攻击时尽量保持稳定。", "⚠️ 考点/易错点：蛋白质相互作用网络由节点和边组成，无标度拓扑组织增加系统稳健性；绝大多数节点连接度低，一般受影响的常是非致命节点，除非扰动过大或高度节点被攻击。"], "code": null, "lang": null, "check": {"q": "关于蛋白质相互作用网络的基本概念，下列说法正确的是？", "o": ["A. 网络由一组元素（节点）和一组二元关系（边）组成", "B. 节点只能表示蛋白质，不能表示基因", "C. 边只能表示物理相互作用", "D. 无标度拓扑会降低系统稳健性"], "a": "A", "e": "网络由一组元素（节点）和一组二元关系（边）组成；节点可表示分子、基因等，边可表示分子相互作用、遗传相互作用等。"}, "cards": [{"front": "蛋白质相互作用网络的基本组成是什么？无标度拓扑组织有什么意义？", "back": "蛋白质相互作用网络由一组元素（节点）和一组二元关系（边）组成。节点可表示分子、基因等，边可表示分子相互作用、遗传相互作用或其他类型相互作用。无标度拓扑组织增加系统稳健性，使网络在部分组件故障、环境改变或外来攻击时尽量保持稳定。", "mnemonic": "节点边，无标度稳", "useImg": false}]}, {"i": 22, "sec": "第五节 信号转导途径", "title": "幽门螺杆菌与酵母蛋白质相互作用网络实例", "notes": "本页给出蛋白质相互作用网络实例。幽门螺杆菌测序后约含1590个潜在蛋白质或ORF；Rain等用酵母双杂交从编码基因组多肽文库中筛选261个蛋白质，得到约1200个相互作用，约占全蛋白质组相互作用的46.6%，并开发PIMRider软件进行图示和基于网络图的功能分析。功能相关基因编码的蛋白质易相互作用，如趋化相关蛋白CheA、CheW、CheY、TlpA形成局部子网络，CheA与CheW、CheY作用，TlpA与CheW作用；HypE-HypF、ScoA-ScoB、RpsR-RpsF、MoaE-MoaD、FtsA-FtsZ等功能相关蛋白对也相互作用。酵母网络中，Uetz等2000年用酵母双杂交识别1004个蛋白质的957个相互作用，发现相互作用蛋白常涉及相同生物学功能；后续Schwikowski等2000年涉及1548个蛋白质的2358个相互作用，63%发生在功能相近蛋白间，76%发生在相同亚细胞定位间。Jeong等2001年用1870个蛋白质、2240个相互作用构建酵母网络，表明网络属无标度网络，节点连接度服从幂律分布，P(k)为节点联系k个蛋白质的概率。", "page": 197, "level": "理解", "img": "assets/img/ch09/p197.jpg", "anim": null, "fig": null, "points": ["幽门螺杆菌测序后约含1590个潜在蛋白质或ORF。", "Rain等用酵母双杂交从编码基因组多肽文库中筛选261个蛋白质，得到约1200个相互作用，约占全蛋白质组相互作用的46.6%。", "开发PIMRider软件进行图示和基于网络图的功能分析。", "功能相关基因编码的蛋白质易相互作用，如趋化相关蛋白CheA、CheW、CheY、TlpA形成局部子网络。", "CheA与CheW、CheY等相互作用，体现功能模块化。", "⚠️ 考点/易错点：幽门螺杆菌约含1590个潜在蛋白质或ORF，Rain等用酵母双杂交筛选261个蛋白质得到约1200个相互作用，约占全蛋白质组相互作用的46.6%；功能相关基因编码的蛋白质易相互作用，如CheA、CheW、CheY、TlpA形成局部子网络。"], "code": null, "lang": null, "check": {"q": "Rain等用酵母双杂交研究幽门螺杆菌蛋白质相互作用时，筛选了多少个蛋白质并得到约1200个相互作用？", "o": ["A. 261个", "B. 1590个", "C. 1200个", "D. 46.6个"], "a": "A", "e": "Rain等用酵母双杂交从编码基因组多肽文库中筛选261个蛋白质，得到约1200个相互作用，约占全蛋白质组相互作用的46.6%。"}, "cards": [{"front": "幽门螺杆菌蛋白质相互作用网络实例中，Rain等得到多少相互作用？约占全蛋白质组相互作用的多少？", "back": "Rain等用酵母双杂交从编码基因组多肽文库中筛选261个蛋白质，得到约1200个相互作用，约占全蛋白质组相互作用的46.6%。", "mnemonic": "261筛，1200互，46.6%", "useImg": false}]}, {"i": 23, "sec": "第五节 信号转导途径", "title": "酵母多蛋白复合物网络与蛋白质新功能发现", "notes": "本页介绍Gavin等2002年利用串联亲和纯化（TAP）和质谱技术分析酿酒酵母多蛋白复合体的工作。共分析1739个基因，其中与人类相关的直系同源物1143个；纯化了589个蛋白质，分属232个不同复合物。图9-23为酵母多蛋白复合物网络图，节点和连线表示蛋白质及复合物关系，不同颜色表示蛋白质复合物在细胞中的作用，如细胞周期、信号转导、转录、DNA修复、染色体结构、蛋白质合成等。研究发现了344种蛋白质的新功能，其中231种以前未报道。该页强调高通量蛋白质相互作用和复合物分析能从网络层面揭示功能模块、保守性和新功能注释，是系统生物学中蛋白质-蛋白质相互作用网络的重要实验基础。", "page": 198, "level": "理解", "img": "assets/img/ch09/p198.jpg", "anim": null, "fig": "图9-23为酵母多蛋白复合物网络图，节点和连线表示蛋白质及复合物关系，不同颜色表示蛋白质复合物在细胞中的作用，如细胞周期、信号转导、转录、DNA修复、染色体结构、蛋白质合成等。", "points": ["Gavin等2002年利用串联亲和纯化（TAP）和质谱技术分析酿酒酵母多蛋白复合体。", "共分析1739个基因，其中与人类相关的直系同源物1143个；纯化了589个蛋白质，分属232个不同复合物。", "图9-23为酵母多蛋白复合物网络图，节点和连线表示蛋白质及复合物关系。", "不同颜色表示蛋白质复合物在细胞中的作用，如细胞周期、信号转导、转录、DNA修复、染色体结构、蛋白质合成等。", "研究发现了344种蛋白质新功能。", "⚠️ 考点/易错点：Gavin等2002年利用串联亲和纯化（TAP）和质谱技术分析酿酒酵母多蛋白复合体，共分析1739个基因，纯化589个蛋白质，分属232个不同复合物，并发现344种蛋白质的新功能，其中231种以前未报道。"], "code": null, "lang": null, "check": {"q": "Gavin等2002年利用串联亲和纯化（TAP）和质谱技术分析酿酒酵母多蛋白复合体时，共纯化了多少个蛋白质？", "o": ["A. 589个", "B. 1739个", "C. 232个", "D. 344个"], "a": "A", "e": "Gavin等共分析1739个基因，纯化了589个蛋白质，分属232个不同复合物，并发现了344种蛋白质的新功能。"}, "cards": [{"front": "Gavin等2002年利用什么技术分析酿酒酵母多蛋白复合体？纯化了多少蛋白质？分属多少复合物？", "back": "Gavin等2002年利用串联亲和纯化（TAP）和质谱技术分析酿酒酵母多蛋白复合体。共分析1739个基因，纯化了589个蛋白质，分属232个不同复合物。", "mnemonic": "TAP质谱，589蛋白232复合物", "useImg": false}]}, {"i": 24, "sec": "第六节 蛋白质-蛋白质相互作用网络", "title": "DNA损伤修复相关蛋白质相互作用网络", "notes": "本页介绍Ho等构建的DNA损伤修复相关蛋白质相互作用网络。以100种蛋白激酶、36种磷酸酶及亚基、86种DNA损伤修复蛋白等为诱饵，共发现3617种蛋白质相互作用，重点研究信号转导与DNA损伤修复网络。图9-24展示该网络，涉及细胞周期、转录、蛋白质降解和DNA修复等过程。网络由已知和新相互作用子集构成，包括86个DNA损伤修复相关蛋白；蓝色箭头表示已知相互作用，红色箭头表示新发现相互作用。该工作表明DNA损伤修复相关蛋白包含许多蛋白复合体，例如RFC复合体由Rfc1、Rfc2、Rfc3、Rfc4和Rfc5相互作用组成；PCNA样复合体由Mec3、Rad17和Ddc1组成，主要传递损伤信息；PRR复合体由Mms2、Ubc13和Rad18组成；MRX复合体由Mre11、Rad50和Xrs2组成，介导同源双链修复；NER复合体涵盖NEF1、NEF3/TFIIH和NEF4等小复合体。读图时应关注节点代表蛋白、边代表相互作用，箭头颜色区分已知与新发现，复合体以密集连接子网呈现。", "page": 199, "level": "掌握", "img": "assets/img/ch09/p199.jpg", "anim": null, "fig": "图9-24展示DNA损伤修复相关蛋白质相互作用网络，涉及细胞周期、转录、蛋白质降解和DNA修复等过程。网络由已知和新相互作用子集构成，包括86个DNA损伤修复相关蛋白；蓝色箭头表示已知相互作用，红色箭头表示新发现相互作用。", "points": ["Ho等构建了DNA损伤修复相关蛋白质相互作用网络。", "以100种蛋白激酶、36种磷酸酶及亚基、86种DNA损伤修复蛋白等为诱饵，共发现3617种蛋白质相互作用。", "重点研究信号转导与DNA损伤修复网络。", "图9-24展示该网络，涉及细胞周期、转录、蛋白质降解和DNA修复等过程。", "网络由已知和新相互作用子集构成，包括86个DNA损伤修复相关蛋白；蓝色箭头表示已知相互作用，红色箭头表示新发现相互作用。", "⚠️ 考点/易错点：Ho等构建的DNA损伤修复相关蛋白质相互作用网络中，蓝色箭头表示已知相互作用，红色箭头表示新发现相互作用，易考颜色与相互作用类型的对应关系。"], "code": null, "lang": null, "check": {"q": "Ho等构建的DNA损伤修复相关蛋白质相互作用网络中，共发现多少种蛋白质相互作用？", "o": ["A. 3617种", "B. 100种", "C. 36种", "D. 86种"], "a": "A", "e": "Ho等以100种蛋白激酶、36种磷酸酶及亚基、86种DNA损伤修复蛋白等为诱饵，共发现3617种蛋白质相互作用。"}, "cards": [{"front": "Ho等构建的DNA损伤修复相关蛋白质相互作用网络中，共发现多少种蛋白质相互作用？蓝色和红色箭头分别表示什么？", "back": "Ho等以100种蛋白激酶、36种磷酸酶及亚基、86种DNA损伤修复蛋白等为诱饵，共发现3617种蛋白质相互作用。蓝色箭头表示已知相互作用，红色箭头表示新发现相互作用。", "mnemonic": "3617互作，蓝知红新", "useImg": false}]}, {"i": 25, "sec": "第六节 蛋白质-蛋白质相互作用网络", "title": "线虫蛋白质相互作用网络与果蝇网络研究背景", "notes": "本页首先展示图9-25线虫蛋白质相互作用网络，节点为蛋白质，按种系发生类着色，反映不同进化来源；网络中包含核心与非核心部分，并标注支架、相互作用等关系，可用于理解线虫蛋白互作网络的整体组织。随后进入果蝇蛋白质相互作用网络部分：黑腹果蝇是高等真核生物遗传学研究的经典材料，基因组大小约180 Mb，有13601个编码蛋白质的ORF。Giot等（2003）用酵母双杂交系统研究果蝇蛋白质相互作用，对13601种ORF进行系统筛选。该页要点是：不同模式生物（线虫、果蝇）的蛋白质相互作用网络构建策略和网络图读法；节点颜色、核心/非核心、支架蛋白等图例含义；酵母双杂交作为高通量互作检测方法。", "page": 200, "level": "理解", "img": "assets/img/ch09/p200.jpg", "anim": null, "fig": "图9-25展示线虫蛋白质相互作用网络，节点为蛋白质，按种系发生类着色，反映不同进化来源。网络中包含核心与非核心部分，并标注支架、相互作用等关系，可用于理解线虫蛋白互作网络的整体组织。", "points": ["图9-25展示线虫蛋白质相互作用网络，节点为蛋白质，按种系发生类着色，反映不同进化来源。", "网络中包含核心与非核心部分，并标注支架、相互作用等关系，可用于理解线虫蛋白互作网络的整体组织。", "黑腹果蝇是高等真核生物遗传学研究的经典材料，基因组大小约180 Mb，有13601个编码蛋白质的ORF。", "Giot等（2003）用酵母双杂交系统研究果蝇蛋白质相互作用。", "对13601个ORF进行系统筛选，构建果蝇蛋白质相互作用网络。", "⚠️ 考点/易错点：Giot等（2003）用酵母双杂交系统对果蝇13601个编码蛋白质的ORF进行系统筛选，注意果蝇基因组约180 Mb、ORF数目及所用技术。"], "code": null, "lang": null, "check": {"q": "关于果蝇蛋白质相互作用网络研究，下列描述正确的是？", "o": ["A. 黑腹果蝇基因组大小约180 Mb，有13601个编码蛋白质的ORF", "B. 果蝇基因组比人类大10倍", "C. Giot等只研究了果蝇的代谢网络", "D. 果蝇不是经典遗传学材料"], "a": "A", "e": "黑腹果蝇是高等真核生物遗传学研究的经典材料，基因组大小约180 Mb，有13601个编码蛋白质的ORF；Giot等用酵母双杂交系统研究果蝇蛋白质相互作用。"}, "cards": [{"front": "黑腹果蝇基因组大小约多少？有多少个编码蛋白质的ORF？Giot等用什么系统研究果蝇蛋白质相互作用？", "back": "黑腹果蝇基因组大小约180 Mb，有13601个编码蛋白质的ORF。Giot等（2003）用酵母双杂交系统研究果蝇蛋白质相互作用。", "mnemonic": "180Mb，13601 ORF，酵母双杂交", "useImg": false}]}, {"i": 26, "sec": "第六节 蛋白质-蛋白质相互作用网络", "title": "人类疾病相关CCSB-HI1蛋白相互作用网络与网络模体引入", "notes": "本页展示图9-26人类疾病相关CCSB-HI1蛋白相互作用网络，来源于Raul等（2005）。图中节点代表蛋白质，边代表相互作用，网络规模较大，用于连接疾病相关蛋白与相互作用组。该页还引入系统生物学中从网络基本组成单元研究生物学功能的思想，即网络模体和网络主题。网络模体定义为网络中比随机网络更多出现的连接模式，是复杂网络的基本构件。理解该页应把握：人类疾病相关蛋白互作网络可用于识别疾病模块和候选基因；网络模体不是单个具体通路，而是反复出现的局部连接模式；后续将用模体分析揭示网络的组织原则和功能模块。", "page": 201, "level": "理解", "img": "assets/img/ch09/p201.jpg", "anim": null, "fig": "图9-26展示人类疾病相关CCSB-HI1蛋白相互作用网络，来源于Raul等（2005）。图中节点代表蛋白质，边代表相互作用，网络规模较大，用于连接疾病相关蛋白与相互作用组。", "points": ["图9-26展示人类疾病相关CCSB-HI1蛋白相互作用网络，来源于Raul等（2005）。", "图中节点代表蛋白质，边代表相互作用，网络规模较大，用于连接疾病相关蛋白与相互作用组。", "系统生物学中从网络基本组成单元研究生物学功能的思想，即网络模体和网络主题。", "网络模体定义为网络中比随机网络更多出现的连接模式，是复杂网络的基本构件。", "人类疾病相关蛋白互作网络可用于识别疾病模块和候选基因。", "⚠️ 考点/易错点：网络模体定义为网络中比随机网络更多出现的连接模式，是复杂网络的基本构件，易与具体通路混淆。"], "code": null, "lang": null, "check": {"q": "网络模体定义为？", "o": ["A. 网络中比随机网络更多出现的连接模式", "B. 任意一个蛋白质", "C. 任意一条代谢途径", "D. 随机网络中出现的所有模式"], "a": "A", "e": "网络模体定义为网络中比随机网络更多出现的连接模式，是复杂网络的基本构件。"}, "cards": [{"front": "什么是网络模体？人类疾病相关CCSB-HI1蛋白相互作用网络来源于谁？", "back": "网络模体定义为网络中比随机网络更多出现的连接模式，是复杂网络的基本构件。人类疾病相关CCSB-HI1蛋白相互作用网络来源于Raul等（2005）。", "mnemonic": "模体超随机，CCSB-HI1 Raul", "useImg": false}]}, {"i": 27, "sec": "第六节 蛋白质-蛋白质相互作用网络", "title": "酵母、线虫和果蝇网络中保守簇的模块化结构", "notes": "本页展示图9-27，显示跨物种保守的蛋白质网络和途径整体图。网络呈明显模块化特点，可分成71个不同区域，每一区域只与特定生物学功能相关。最大保守模块涉及蛋白质降解（右下角）、RNA多聚腺苷酸化与剪接（左下角）、蛋白质磷酸化与信号转导（右上角）；其他区域涉及DNA合成、核-胞质运输和蛋白质折叠。图中还显示不同模块之间有保守连接。图例按GO细胞过程分类，如细胞增殖、胞内运输、稳态、DNA代谢、RNA定位、蛋白质代谢、转录调控等，并用共享蛋白质比例标注模块间关系。在同一蛋白复合体中蛋白质有相同或相似功能的假设下，可预测新蛋白质功能：共预测酵母176个、线虫1139个、果蝇1294个以前未见功能注释的蛋白质功能。Lee等（2006）研究酵母4738个蛋白质、1129个相互作用形成的网络，发现大多数保守模体可分为3节点等形式。", "page": 202, "level": "掌握", "img": "assets/img/ch09/p202.jpg", "anim": null, "fig": "图9-27显示跨物种保守的蛋白质网络和途径整体图。网络呈明显模块化特点，可分成71个不同区域，每一区域只与特定生物学功能相关。最大保守模块涉及蛋白质降解（右下角）、RNA多聚腺苷酸化与剪接（左下角）、蛋白质磷酸化与信号转导（右上角）；其他区域涉及DNA合成、核-胞质运输和蛋白质折叠。图中还显示不同模块之间有保守连接。图例按GO细胞过程分类，如细胞增殖、胞内运输、稳态、DNA代谢、RNA定等。", "points": ["图9-27显示跨物种保守的蛋白质网络和途径整体图。", "网络呈明显模块化特点，可分成71个不同区域，每一区域只与特定生物学功能相关。", "最大保守模块涉及蛋白质降解（右下角）、RNA多聚腺苷酸化与剪接（左下角）、蛋白质磷酸化与信号转导（右上角）。", "其他区域涉及DNA合成、核-胞质运输和蛋白质折叠。", "图中还显示不同模块之间有保守连接；图例按GO细胞过程分类，如细胞增殖、胞内运输、稳态、DNA代谢、RNA定等。", "⚠️ 考点/易错点：图9-27显示跨物种保守网络可分为71个模块化区域，最大保守模块涉及蛋白质降解、RNA多聚腺苷酸化与剪接、蛋白质磷酸化与信号转导，注意模块数目与功能对应。"], "code": null, "lang": null, "check": {"q": "图9-27显示跨物种保守的蛋白质网络和途径整体图，其最大保守模块涉及？", "o": ["A. 蛋白质降解、RNA多聚腺苷酸化与剪接、蛋白质磷酸化与信号转导", "B. 仅DNA复制", "C. 仅细胞分裂", "D. 仅代谢物运输"], "a": "A", "e": "最大保守模块涉及蛋白质降解（右下角）、RNA多聚腺苷酸化与剪接（左下角）、蛋白质磷酸化与信号转导（右上角）。"}, "cards": [{"front": "图9-27中跨物种保守网络可分成多少个不同区域？最大保守模块涉及哪些功能？", "back": "网络呈明显模块化特点，可分成71个不同区域，每一区域只与特定生物学功能相关。最大保守模块涉及蛋白质降解（右下角）、RNA多聚腺苷酸化与剪接（左下角）、蛋白质磷酸化与信号转导（右上角）。", "mnemonic": "71区，降解剪接磷酸化", "useImg": false}]}, {"i": 28, "sec": "第六节 蛋白质-蛋白质相互作用网络", "title": "整合生物网络中的模体与网络主题", "notes": "本页指出单独研究一种网络可能丢失多种相互作用结合产生的过程或功能，因此需要发展包含多种相互作用的整合生物网络并研究其模体特征。图9-28展示酵母蛋白相互作用网络中3、4节点模体，包括#3-0、#3-1、#4-0、#4-1等拓扑类型。Yeger-Lotem等（2004）分析由转录调控和蛋白质相互作用组成的整合网络，发现模体大多为2、3、4节点，说明网络主要由小网络模体组成，可视为基本构件。图中黑色双向箭头边表示蛋白质-蛋白质相互作用，红色单向箭头边表示转录调控（转录因子指向目标基因）。若模体出现次数超过5次即视为模体。结果：可能的2蛋白模体共5种，网络中只发现混合反馈环模体；可能的3蛋白模体共100种，网络中发现蛋白环、相互作用因子调控第3个基因、转录调控组成的向前反馈环、共调控相互作用蛋白和混合反馈环5种；可能的4蛋白模体超过4000种，网络中发现63种。Zhang等（2005）以酵母网络为例，考虑5种相互作用类型，定义网络主题，并区分网络模体与网络主题。蛋白质相互作用可以是直接物理作用、遗传作用、合成致病或致死（SSL），2基因还可通过转录序列同源或表达相关等方式作用。工作中使用3066个SSL相互作用、40438个蛋白质序列同源关系。", "page": 203, "level": "掌握", "img": "assets/img/ch09/p203.jpg", "anim": null, "fig": "图9-28展示酵母蛋白相互作用网络中3、4节点模体，包括#3-0、#3-1、#4-0、#4-1等拓扑类型。Yeger-Lotem等（2004）分析由转录调控和蛋白质相互作用组成的整合网络，发现模体大多为2、3、4节点，说明网络主要由小网络模体组成，可视为基本构件。图中黑色双箭头等表示不同相互作用类型。", "points": ["单独研究一种网络可能丢失多种相互作用结合产生的过程或功能，因此需要发展包含多种相互作用的整合生物网络并研究其模体特征。", "图9-28展示酵母蛋白相互作用网络中3、4节点模体，包括#3-0、#3-1、#4-0、#4-1等拓扑类型。", "Yeger-Lotem等（2004）分析由转录调控和蛋白质相互作用组成的整合网络。", "发现模体大多为2、3、4节点，说明网络主要由小网络模体组成，可视为基本构件。", "图中黑色双箭头等表示不同相互作用类型。", "⚠️ 考点/易错点：Yeger-Lotem等（2004）分析转录调控与蛋白质相互作用组成的整合网络，发现模体大多为2、3、4节点；黑色双向箭头边表示蛋白质-蛋白质相互作用，注意边颜色/方向含义。"], "code": null, "lang": null, "check": {"q": "Yeger-Lotem等（2004）分析由转录调控和蛋白质相互作用组成的整合网络，发现模体大多为？", "o": ["A. 2、3、4节点", "B. 10、20、30节点", "C. 仅1节点", "D. 仅100节点"], "a": "A", "e": "Yeger-Lotem等分析整合网络，发现模体大多为2、3、4节点，说明网络主要由小网络模体组成，可视为基本构件。"}, "cards": [{"front": "Yeger-Lotem等（2004）分析由什么组成的整合网络？发现模体大多为多少节点？", "back": "Yeger-Lotem等（2004）分析由转录调控和蛋白质相互作用组成的整合网络，发现模体大多为2、3、4节点，说明网络主要由小网络模体组成，可视为基本构件。", "mnemonic": "转录+蛋白，2/3/4节点", "useImg": false}]}, {"i": 29, "sec": "第六节 蛋白质-蛋白质相互作用网络", "title": "网络模体与网络主题的示例集合", "notes": "本页为整页图，展示图9-29，包含(a)至(f)六个模体集合Motif set A-F，用于说明网络模体与网络主题的区别。每个集合给出模体示例和主题示例，涉及不同相互作用类型和节点组合。图中可能包含蛋白质-蛋白质相互作用、转录调控、遗传相互作用、SSL等边的表示；节点可能代表基因或蛋白质，边方向与颜色区分作用类型。读图时应关注：模体是在网络中显著富集的局部连接模式，主题是更广义的、可能包含不同具体实现但功能相关的网络模式；同一主题可由多个模体实例组成。该图配合正文说明Zhang等（2005）如何定义网络主题，并明确区分模体与主题概念。学习时应能识别模体拓扑、理解出现次数阈值（如超过5次）以及模体与主题在系统生物学中的不同用途。", "page": 204, "level": "理解", "img": "assets/img/ch09/p204.jpg", "anim": null, "fig": "图9-29包含(a)至(f)六个模体集合Motif set A-F，用于说明网络模体与网络主题的区别。每个集合给出模体示例和主题示例，涉及不同相互作用类型和节点组合。图中可能包含蛋白质-蛋白质相互作用、转录调控、遗传相互作用、SSL等边的表示；节点可能代表基因或蛋白质，边方向与颜色区分作用类型。读图时应关注：模体是在网络中显著富集的局部连接模式，主题是更广义的、可能包含不同具体模体的连接模式。", "points": ["图9-29包含(a)至(f)六个模体集合Motif set A-F，用于说明网络模体与网络主题的区别。", "每个集合给出模体示例和主题示例，涉及不同相互作用类型和节点组合。", "图中可能包含蛋白质-蛋白质相互作用、转录调控、遗传相互作用、SSL等边的表示。", "节点可能代表基因或蛋白质，边方向与颜色区分作用类型。", "读图时应关注：模体是在网络中显著富集的局部连接模式，主题是更广义的、可能包含不同具体模体的连接模式。", "⚠️ 考点/易错点：网络模体是在网络中显著富集的局部连接模式，网络主题是更广义、可能包含不同具体实现但功能相关的网络模式，二者易混。"], "code": null, "lang": null, "check": {"q": "关于网络模体与网络主题的区别，下列说法正确的是？", "o": ["A. 模体是在网络中显著富集的局部连接模式，主题是更广义的、可能包含不同具体实现但功能相关的网络模式", "B. 模体和主题完全相同", "C. 主题只包含一个节点", "D. 模体不能统计显著性"], "a": "A", "e": "模体是在网络中显著富集的局部连接模式，主题是更广义的、可能包含不同具体实现但功能相关的网络模式；同一主题可由多种模体实现。"}, "cards": [{"front": "网络模体与网络主题有什么区别？图9-29展示了什么？", "back": "模体是在网络中显著富集的局部连接模式，主题是更广义的、可能包含不同具体模体的连接模式。图9-29包含(a)至(f)六个模体集合Motif set A-F，用于说明网络模体与网络主题的区别。", "mnemonic": "模体富集，主题广义", "useImg": false}]}, {"i": 30, "sec": "第七节 虚拟细胞", "title": "虚拟细胞的概念与构建", "notes": "本页首先展示了对应于“补偿蛋白和复合物/过程”主题的4节点模体，包括模体、模体统计学列表、模体实例和形成的网络主题实例。随后进入第七节“虚拟细胞”，介绍了虚拟细胞（virtual cell）的定义：在实验数据和理论基础上，结合生命科学、计算机科学、数学等学科的原理和技术，对细胞的结构和功能进行分析和整合，构建的一种对细胞内外部生命活动现象及过程进行模拟和预测的虚拟系统，以探索细胞生命活动的潜在规律。虚拟细胞亦称人工细胞（artificial cell）或电子细胞（e-cell）。一般认为虚拟细胞由4部分组成：控制界面、计算机存储分析和控制系统、数学计算系统、反应界面。其构建过程一般包括生物数据收集、整理、计算分析、向虚拟细胞数学模型的转化以及测试和维护。虚拟细胞构建复杂，不同细胞、不同虚拟对象和功能，构建形式差异大，需要反复验证和完善。以虚拟细胞为平台，借助计算机辅助人脑工作，可以更好地掌握和利用细胞生命活动规律，创造人工生命，加速生命科学和信息科学的发展。", "page": 205, "level": "掌握", "img": "assets/img/ch09/p205.jpg", "anim": null, "fig": "本页展示了对应于“补偿蛋白和复合物/过程”主题的4节点模体，包括模体、模体统计学列表、模体实例和形成的网络主题实例，用于说明网络模体在系统生物学中的表示方式。", "points": ["展示对应“补偿蛋白和复合物/过程”主题的4节点模体，包括模体、模体统计学列表、模体实例和形成的网络主题实例。", "进入第七节“虚拟细胞”，给出虚拟细胞（virtual cell）的定义。", "虚拟细胞是在实验数据和理论基础上，结合生命科学、计算机科学、数学等学科的原理和技术构建的虚拟系统。", "虚拟细胞用于对细胞结构和功能进行分析和整合，模拟和预测细胞内外部生命活动现象及过程。", "虚拟细胞的目的是探索细胞生命活动的潜在规律。", "⚠️ 考点/易错点：虚拟细胞定义：在实验数据和理论基础上，结合生命科学、计算机科学、数学等学科原理和技术，对细胞结构和功能进行分析整合，构建模拟和预测细胞内外部生命活动现象的虚拟系统，亦称人工细胞。"], "code": null, "lang": null, "check": {"q": "虚拟细胞（virtual cell）的定义是？", "o": ["A. 在实验数据和理论基础上，结合多学科原理和技术，对细胞结构和功能进行分析整合，构建的模拟和预测虚拟系统", "B. 一种真实的细胞培养物", "C. 仅由计算机生成的随机图像", "D. 一种只用于DNA测序的软件"], "a": "A", "e": "虚拟细胞是在实验数据和理论基础上，结合生命科学、计算机科学、数学等学科的原理和技术，对细胞的结构和功能进行分析和整合，构建的一种对细胞内外部生命活动现象及过程进行模拟和预测的虚拟系统。"}, "cards": [{"front": "什么是虚拟细胞（virtual cell）？", "back": "虚拟细胞是在实验数据和理论基础上，结合生命科学、计算机科学、数学等学科的原理和技术，对细胞的结构和功能进行分析和整合，构建的一种对细胞内外部生命活动现象及过程进行模拟和预测的虚拟系统，以探索细胞生命活动的潜在规律。", "mnemonic": "实验理论为基础，多学科整合，模拟预测细胞活动。", "useImg": false}]}, {"i": 31, "sec": "第七节 虚拟细胞", "title": "生物学网络与Cytoscape简介", "notes": "本页开始第八节“生物学网络的构建、分析与可视化”。首先指出海量多组学数据提供了大量关系数据，网络分析已成为生物信息学不可或缺的手段。生物学网络脱胎于图论，以结构、关系、路径等拓扑性质为特征，是一种用网络图像体现关系模型的方法。生物学网络可研究多种关系数据，如分子间结构相似性、药物-靶点关系、基因共表达、RNA调控等。生物学网络研究是现代系统生物学重要组成部分，也是目前相对最成熟的领域。本节以Cytoscape为例介绍网络构建、分析及可视化方法。Cytoscape是由美国西雅图系统生物学研究所开发并于2002年发布的开源软件，主要用于分子互作网络可视化和复杂网络分析。最新版本为3.5.1，可在多种操作系统运行，官方网址：http://cytoscape.org/。Cytoscape需要Java运行环境支持，安装前需具备Java。Cytoscape优势：操作丰富，包含大量插件，支持多种格式导入导出，良好支持生物数据专用格式（如SBML）。在系统生物学领域应用突出，也可用于其他领域，提供官方JavaScript库用于网页开发。类似软件包括Gephi等，但Cytoscape在生物数据支持上更优。", "page": 206, "level": "掌握", "img": "assets/img/ch09/p206.jpg", "anim": null, "fig": null, "points": ["进入第八节“生物学网络的构建、分析与可视化”。", "海量多组学数据提供了大量关系数据，网络分析已成为生物信息学不可或缺的手段。", "生物学网络脱胎于图论，以结构、关系、路径等拓扑性质为特征，是用网络图像体现关系模型的方法。", "生物学网络可研究分子间结构相似性、药物-靶点关系、基因共表达、RNA调控等多种关系数据。", "生物学网络研究是现代系统生物学重要组成部分，也是目前相对最成熟的领域；本节以Cytoscape为例介绍。", "⚠️ 考点/易错点：生物学网络脱胎于图论，以结构、关系、路径等拓扑性质为特征；本节以Cytoscape为例介绍网络构建、分析与可视化，注意其定位。"], "code": null, "lang": null, "check": {"q": "关于生物学网络与Cytoscape，下列说法正确的是？", "o": ["A. 生物学网络脱胎于图论，以结构、关系、路径等拓扑性质为特征", "B. 生物学网络与图论无关", "C. Cytoscape只能用于DNA序列比对", "D. 生物学网络不能研究基因共表达"], "a": "A", "e": "生物学网络脱胎于图论，以结构、关系、路径等拓扑性质为特征，是一种用网络图像体现关系模型的方法；Cytoscape是网络构建、分析及可视化的工具。"}, "cards": [{"front": "生物学网络的定义和特点是什么？", "back": "生物学网络脱胎于图论，以结构、关系、路径等拓扑性质为特征，是一种用网络图像体现关系模型的方法。生物学网络可研究多种关系数据，如分子间结构相似性、药物-靶点关系、基因共表达、RNA调控等。", "mnemonic": "图论为基，拓扑为征，关系为模。", "useImg": false}]}, {"i": 32, "sec": "第七节 虚拟细胞", "title": "Cytoscape基本操作与网络分析", "notes": "本页继续介绍Cytoscape的使用。首先展示Cytoscape主界面（图9-31）。然后详细说明节点和连线的样式改变：在可视化区域右键点击唤出快捷菜单，对选中节点和连线样式单独设置；在控制面板Style栏中实现网络全局、映射调整和选中节点/连线的样式设置。网络分析：在菜单栏选择NetworkAnalyzer运行网络分析，在数据栏生成新列展示网络节点和连线的具体属性，计算节点的度与连线的加权。子网络构建：选择感兴趣节点，使用菜单栏或工具栏选项构建子网络，选择相应层级的邻接节点构建多层子网络。文件操作包括：导入网络文件（通过菜单栏或工具栏导入文件，选择文件位置、数据格式和属性，导入网络视图，可通过对话框调整分隔格式，Cytoscape对文件格式适应良好，可导入各种符号分隔的数据表）；导入表格（导入表格文件，多为节点或连线属性注释，选择文件位置、格式和属性，导入数据栏用于后续操作，同样可调整分隔格式）；导出网络图像（调整网络视图大小，确保不超出可视化区域边缘，利用菜单栏或工具栏导出图像，选择文件导出位置和图像格式，支持JPEG、PDF、PNG等）。最后开始介绍Cytoscape实现互作网络可视化，使用安装目录中的示例数据构建简单蛋白质互作网络，在sampleData/目录中找到galFiltered.sif，使用导入网络操作。", "page": 207, "level": "掌握", "img": "assets/img/ch09/p207.jpg", "anim": null, "fig": "图9-31展示Cytoscape主界面，包括菜单栏、控制面板、可视化区域和数据栏等主要组成部分，用于说明Cytoscape的基本操作界面。", "points": ["展示Cytoscape主界面（图9-31）。", "节点和连线样式改变：在可视化区域右键点击唤出快捷菜单，对选中节点和连线样式单独设置。", "在控制面板Style栏中可实现网络全局、映射调整和选中节点/连线的样式设置。", "网络分析：在菜单栏选择NetworkAnalyzer运行网络分析，在数据栏生成新列展示网络节点和连线的具体属性。", "NetworkAnalyzer可计算节点的度与连线的加权，并支持子网分析等。", "⚠️ 考点/易错点：Cytoscape中节点/连线样式可右键单独设置，也可在Style栏全局或映射调整；NetworkAnalyzer运行后会在数据栏新增列，计算节点度与连线加权，注意区分局部样式与全局样式。"], "code": null, "lang": null, "check": {"q": "在Cytoscape中，运行网络分析通常选择哪个菜单？", "o": ["A. NetworkAnalyzer", "B. File", "C. Edit", "D. Help"], "a": "A", "e": "在菜单栏选择NetworkAnalyzer运行网络分析，在数据栏生成新列展示网络节点和连线的具体属性，计算节点的度与连线的加权。"}, "cards": [{"front": "在Cytoscape中如何运行网络分析并查看结果？", "back": "在菜单栏选择NetworkAnalyzer运行网络分析，在数据栏生成新列展示网络节点和连线的具体属性，计算节点的度与连线的加权。", "mnemonic": "菜单NetworkAnalyzer，数据栏出新列，度与加权算出来。", "useImg": false}]}, {"i": 33, "sec": "第七节 虚拟细胞", "title": "Cytoscape网络可视化与属性映射", "notes": "本页展示导入示例数据galFiltered.sif的界面（图9-32）。在可视化界面查看导入的网络，使用菜单栏Layouts菜单调整网络布局。使用控制面板Style页面对网络节点、连线及整体进行手动调整。也可以使用导入表格操作加入附加表格文件，作为网络属性，映射到对应节点或连线上。在弹出的对话框中完成正确映射后，观察Cytoscape下方数据栏，即可找到增加的节点或连线属性，据此在控制面板Style页面对网络节点、连线及整体进行批量调整。如果没有附加表格，也可以直接通过网络分析工具创建网络的基本统计属性。点击顺序为：Tools → Network Analyzer → Network Analysis → Analyze Network（图9-33）。增加基本统计属性后，可以此为参数设置网络的Style。图9-33展示了Network Statistics of galFiltered.sif (undirected)的界面，包括Closeness Centrality、Stress Centrality Distribution、Neighborhood Connectivity Distribution、Betweenness等统计量。这些统计属性有助于理解网络拓扑特征，如节点中心性、连接度分布等，为后续分析提供基础。", "page": 208, "level": "掌握", "img": "assets/img/ch09/p208.jpg", "anim": null, "fig": "图9-32展示导入示例数据galFiltered.sif的界面，用于说明如何将网络数据导入Cytoscape，并在可视化界面中查看和调整网络。", "points": ["展示导入示例数据galFiltered.sif的界面（图9-32）。", "在可视化界面查看导入的网络，使用菜单栏Layouts菜单调整网络布局。", "使用控制面板Style页面对网络节点、连线及整体进行手动调整。", "可使用导入表格操作加入附加表格文件，作为网络属性，映射到对应节点或连线上。", "在对话框中完成正确映射后，观察Cytoscape下方数据栏，即可找到增加的节点或连线属性，并据此在控制面板Style中进行可视化映射。", "⚠️ 考点/易错点：导入galFiltered.sif后可用Layouts调整布局；附加表格文件需正确映射到节点或连线，映射成功后数据栏出现新属性列，再据此在Style页批量调整，易错点是映射字段选错导致属性无法关联。"], "code": null, "lang": null, "check": {"q": "在Cytoscape中导入示例数据galFiltered.sif后，可使用哪个菜单调整网络布局？", "o": ["A. Layouts菜单", "B. File菜单", "C. Help菜单", "D. Plugins菜单"], "a": "A", "e": "在可视化界面查看导入的网络，使用菜单栏Layouts菜单调整网络布局；使用控制面板Style页面对网络节点、连线及整体进行手动调整。"}, "cards": [{"front": "在Cytoscape中如何将附加表格文件映射为网络属性？", "back": "使用导入表格操作加入附加表格文件，作为网络属性，映射到对应节点或连线上。在弹出的对话框中完成正确映射后，观察Cytoscape下方数据栏，即可找到增加的节点或连线属性，据此在控制面板Style中进行可视化映射。", "mnemonic": "导入表格，映射属性，数据栏查看，Style中展示。", "useImg": false}]}, {"i": 34, "sec": "第七节 虚拟细胞", "title": "Cytoscape插件与思考题", "notes": "本页介绍Cytoscape插件。Cytoscape具备丰富的插件支持，例如用于GO富集分析的BiNGO，以及用于文献挖掘的Agilent Literature Search。可以在菜单中打开插件管理器（图9-34），搜索所需插件进行下载安装，也可以通过来自网络或其他位置的jar文件安装，安装后即可在菜单栏插件列表中点击运行。Cytoscape在丰富插件支持下，功能更强大，更受多领域研究人员青睐。图9-34展示插件管理器界面，包括Install Apps、Currently Installed、Check for Updates等选项。随后是思考题部分，包括：2. 简述系统生物学与分子生物学的差异；3. 为什么说整合是系统生物学的灵魂；4. 概述系统生物学的基本工作框架；5. 总结酵母双杂交系统的基本原理；6. 列举几种超高分率荧光显微镜技术；7. 给出了一个表达矩阵M，每行表示缺失该行基因情况下其他基因的表达水平，每列表示该基因在各种基因缺失试验下的表达水平，要求以此数据为基础构建基因表达数据的网络模型。矩阵包含wt、a1、a2、a3等行和列，数值如3.750、8.939等。", "page": 209, "level": "理解", "img": "assets/img/ch09/p209.jpg", "anim": null, "fig": "图9-34展示Cytoscape插件管理器界面，用于说明如何搜索、下载和安装插件，以及安装后在菜单栏插件列表中运行插件。", "points": ["Cytoscape具备丰富的插件支持。", "例如用于GO富集分析的BiNGO，以及用于文献挖掘的Agilent Literature Search。", "可以在菜单中打开插件管理器（图9-34），搜索所需插件进行下载安装。", "也可以通过来自网络或其他位置的jar文件安装插件，安装后即可在菜单栏插件列表中点击运行。", "Cytoscape在丰富插件支持下，功能更强大，更受多领域研究人员青睐。", "⚠️ 考点/易错点：Cytoscape插件可通过插件管理器搜索安装，也可用jar文件安装；BiNGO用于GO富集分析，Agilent Literature Search用于文献挖掘，注意插件安装后需在插件菜单中运行。"], "code": null, "lang": null, "check": {"q": "下列哪项是Cytoscape的插件示例？", "o": ["A. BiNGO和Agilent Literature Search", "B. BLAST和ClustalW", "C. Excel和Word", "D. Linux和Windows"], "a": "A", "e": "Cytoscape具备丰富的插件支持，例如用于GO富集分析的BiNGO，以及用于文献挖掘的Agilent Literature Search。"}, "cards": [{"front": "Cytoscape插件有什么作用？举例说明。", "back": "Cytoscape具备丰富的插件支持，例如用于GO富集分析的BiNGO，以及用于文献挖掘的Agilent Literature Search。可以在菜单中打开插件管理器搜索所需插件进行下载安装，也可以通过jar文件安装，安装后即可在菜单栏插件列表中点击运行。", "mnemonic": "插件丰富，BiNGO富集，Agilent文献挖掘。", "useImg": false}]}, {"i": 35, "sec": "第七节 虚拟细胞", "title": "思考题与参考文献", "notes": "本页继续列出思考题：8. 以细菌化学趋向为例，查阅文献开展构建信号转导模型的工作；9. 总结网络分类法；10. 学习几种重要的蛋白质相互作用数据库（如DIP和BIND等）；11. 从网上学习诸如KEGG的储存途径或网络的数据库；12. 何为网络模体；13. 如何用网络模体概念推测蛋白质功能；14. 以酵母蛋白相互作用数据为对象，使用Aisee软件构建相互作用网络图；15. 学习PATHBLAST类似软件，尝试比较酵母、线虫、果蝇蛋白质相互作用网络，从中找出一些保守的网络模体；16. 何为网络模块化；17. 列举常见的几种三节点网络模体，并说明其对应的网络主题。最后列出参考文献，包括北野宏明2007年《系统生物学基础》、陈铭2007年系统生物学重要问题、冯团诚和庄南生2007年虚拟细胞模型研究进展、张先恩2008年细胞工厂和生物纳米机器、Albert等2000年复杂网络的错误和攻击容忍度、Aronheim等1997年检测蛋白质相互作用的新方法、Betzig等。这些文献为系统生物学和网络分析提供了理论基础。", "page": 210, "level": "了解", "img": "assets/img/ch09/p210.jpg", "anim": null, "fig": null, "points": ["思考题8：以细菌化学趋向为例，查阅文献开展构建信号转导模型的工作。", "思考题9：总结网络分类法。", "思考题10：学习几种重要的蛋白质相互作用数据库（如DIP和BIND等）。", "思考题11：从网上学习诸如KEGG的储存途径或网络的数据库。", "思考题12-15：涉及网络模体、用网络模体概念推测蛋白质功能、以酵母蛋白相互作用数据为对象使用Aisee软件构建相互作用网络图、学习PATHBLAST类工具等。", "⚠️ 考点/易错点：思考题涉及信号转导模型构建、网络分类法、蛋白质相互作用数据库（DIP、BIND）、KEGG、网络模体及功能推测、Aisee和PATHBLAST等，易考网络模体概念及其推测蛋白质功能的思路。"], "code": null, "lang": null, "check": {"q": "思考题中，“何为网络模体”对应的题号是？", "o": ["A. 12", "B. 8", "C. 9", "D. 15"], "a": "A", "e": "思考题第12题为“何为网络模体”；第8题以细菌化学趋向为例构建信号转导模型，第9题总结网络分类法，第15题学习PATHBLAST类似软件。"}, "cards": [{"front": "本页思考题中，关于网络模体的两个问题是什么？", "back": "12. 何为网络模体；13. 如何用网络模体概念推测蛋白质功能。", "mnemonic": "模体定义，模体推功能。", "useImg": false}]}, {"i": 36, "sec": "第八节 生物学网络的构建、分析与可视化", "title": "系统生物学相关文献（一）", "notes": "本页为《生物信息学》（陈铭第三版）第九章第八节“生物学网络的构建、分析与可视化”的参考文献页，列出了系统生物学与蛋白质相互作用研究中的若干经典文献。内容包括：Gavin等（2002）利用系统性质谱分析酵母蛋白质复合体，揭示蛋白质组的功能组织；Giot等（2003）构建果蝇蛋白质相互作用图谱；Ho等（2002）通过质谱系统鉴定酿酒酵母蛋白质复合体；Hope和Struhl（1986）对酵母转录激活蛋白GCN4进行功能解剖；Huang等（2008）利用随机光学重建显微镜实现三维超分辨成像；Ideker等（2001）提出解码生命的新方法。这些文献涵盖了蛋白质复合体质谱鉴定、酵母双杂交及衍生技术、蛋白质相互作用图谱构建、超分辨成像等系统生物学核心技术，是理解生物学网络构建实验基础的重要参考资料。学习时应关注各文献所采用的技术路线及其在系统生物学发展中的意义。", "page": 211, "level": "了解", "img": "assets/img/ch09/p211.jpg", "anim": null, "fig": null, "points": ["本页为《生物信息学》（陈铭第三版）第九章第八节“生物学网络的构建、分析与可视化”的参考文献页。", "列出系统生物学与蛋白质相互作用研究中的若干经典文献。", "Gavin等（2002）利用系统性质谱分析酵母蛋白质复合体，揭示蛋白质组的功能组织。", "Giot等（2003）构建果蝇蛋白质相互作用图谱。", "Ho等（2002）通过质谱系统鉴定酿酒酵母蛋白质复合体；Hope和Struhl（1986）对酵母转录激活蛋白等开展研究。", "⚠️ 考点/易错点：该页为参考文献页，易考经典文献与对应贡献的匹配，如Gavin等（2002）系统性质谱分析酵母蛋白质复合体、Giot等（2003）果蝇蛋白质相互作用图谱、Ho等（2002）质谱鉴定酵母蛋白质复合体。"], "code": null, "lang": null, "check": {"q": "Gavin等（2002）利用系统性质谱分析酵母蛋白质复合体，主要揭示了什么？", "o": ["A. 蛋白质组的功能组织", "B. DNA复制起始机制", "C. 线粒体呼吸链结构", "D. 光合作用机制"], "a": "A", "e": "Gavin等（2002）利用系统性质谱分析酵母蛋白质复合体，揭示蛋白质组的功能组织；Giot等（2003）构建果蝇蛋白质相互作用图谱。"}, "cards": [{"front": "Gavin等（2002）和Giot等（2003）分别做了什么研究？", "back": "Gavin等（2002）利用系统性质谱分析酵母蛋白质复合体，揭示蛋白质组的功能组织；Giot等（2003）构建果蝇蛋白质相互作用图谱。", "mnemonic": "Gavin酵母质谱，Giot果蝇互作。", "useImg": false}]}, {"i": 37, "sec": "第八节 生物学网络的构建、分析与可视化", "title": "系统生物学相关文献（二）", "notes": "本页继续列出系统生物学与网络研究的相关文献，涉及酵母三杂交系统、代谢网络全局性质、配体-受体相互作用、计算机模拟生物学、RNA-蛋白质相互作用三杂交系统、幽门螺杆菌蛋白质相互作用图谱等。具体包括：Osborne等（1995）利用酵母三杂交系统遗传检测反式磷酸化ITAM-SH2相互作用；Ouzounis和Karp（2000）分析大肠杆菌代谢图的全局性质；Ozenberger和Young（1995）在酵母中研究造血超家族配体与受体的功能相互作用；Palsson（2000）讨论计算机模拟生物学面临的挑战；Putz等（1996）建立分析检测RNA-蛋白质相互作用的三杂交系统；Rain等（2001）构建幽门螺杆菌蛋白质-蛋白质相互作用图谱。这些文献反映了系统生物学在相互作用检测方法、代谢网络分析和计算模拟等方面的进展，为生物学网络的构建与分析提供了方法学基础。", "page": 212, "level": "了解", "img": "assets/img/ch09/p212.jpg", "anim": null, "fig": null, "points": ["本页继续列出系统生物学与网络研究的相关文献。", "涉及酵母三杂交系统、代谢网络全局性质、配体-受体相互作用、计算机模拟生物学、RNA-蛋白质相互作用三杂交系统、幽门螺杆菌蛋白质相互作用图谱等。", "Osborne等（1995）利用酵母三杂交系统遗传检测反式磷酸化ITAM-SH2相互作用。", "Ouzounis和Karp（2000）分析大肠杆菌代谢图的全局性质。", "Ozenberger和Young（1995）等在相关领域开展研究。", "⚠️ 考点/易错点：该页继续列参考文献，易考酵母三杂交系统、代谢网络全局性质、配体-受体相互作用、幽门螺杆菌蛋白质相互作用图谱等研究对应的作者与年份，注意与上一页文献区分。"], "code": null, "lang": null, "check": {"q": "Ouzounis和Karp（2000）分析了大肠杆菌代谢图的什么性质？", "o": ["A. 全局性质", "B. 仅局部酶活性", "C. 仅基因序列", "D. 仅蛋白质结构"], "a": "A", "e": "Ouzounis和Karp（2000）分析大肠杆菌代谢图的全局性质；Osborne等（1995）利用酵母三杂交系统遗传检测反式磷酸化ITAM-SH2相互作用。"}, "cards": [{"front": "Osborne等（1995）和Ouzounis与Karp（2000）分别研究了什么？", "back": "Osborne等（1995）利用酵母三杂交系统遗传检测反式磷酸化ITAM-SH2相互作用；Ouzounis和Karp（2000）分析大肠杆菌代谢图的全局性质。", "mnemonic": "Osborne三杂交ITAM-SH2，Ouzounis大肠杆菌代谢图。", "useImg": false}]}], "mcq": [{"id": "ch09_mcq_1", "mod": "第九章 系统生物学", "modI": 0, "q": "系统生物学的主要目标是：", "o": ["A. 研究单个基因的功能", "B. 通过整合大量组成成分之间的相互作用理解细胞中复杂的生物系统", "C. 仅研究蛋白质的结构", "D. 开发新的实验技术"], "a": "B", "e": "系统生物学的目的是通过整合大量包括基因、蛋白质和代谢物组成成分之间的相互作用理解细胞中复杂的生物系统。", "kp": "ch09_s0_0"}, {"id": "ch09_mcq_2", "mod": "第九章 系统生物学", "modI": 0, "q": "下列哪项不是系统生物学全面性测量的分类？", "o": ["A. 组分的全面性", "B. 时空完备性", "C. 内容的全面性", "D. 数据的随机性"], "a": "D", "e": "全面性分为组分的全面性、时空完备性和内容的全面性三类。", "kp": "ch09_s0_4"}, {"id": "ch09_mcq_3", "mod": "第九章 系统生物学", "modI": 0, "q": "在基因调控网络模型中，有向边权重因子的正负代表：", "o": ["A. 激活或抑制", "B. 表达水平高低", "C. 蛋白质浓度", "D. 降解速率"], "a": "A", "e": "有向边权重因子的正负代表作用于目标基因的激活或抑制。", "kp": "ch09_s0_9"}, {"id": "ch09_mcq_4", "mod": "第九章 系统生物学", "modI": 0, "q": "酵母半乳糖利用系统中，编码催化转化半乳糖为葡萄糖-6-磷酸的基因不包括：", "o": ["A. GAL1", "B. GAL5", "C. GAL7", "D. GAL4"], "a": "D", "e": "GAL4是转录因子，不是催化酶。催化酶包括GAL1、GAL5、GAL7和GAL10。", "kp": "ch09_s0_11"}, {"id": "ch09_mcq_5", "mod": "第九章 系统生物学", "modI": 0, "q": "细菌化学趋向中，磷酸化的CheY与鞭毛马达蛋白相互作用诱导：", "o": ["A. 逆时针旋转", "B. 顺时针旋转", "C. 停止旋转", "D. 随机旋转"], "a": "B", "e": "磷酸-CheY与鞭毛马达蛋白相互作用诱导顺时针旋转。", "kp": "ch09_s0_13"}, {"id": "ch09_mcq_6", "mod": "第九章 系统生物学", "modI": 0, "q": "无标度网络的连接分布遵循：", "o": ["A. 泊松分布", "B. 正态分布", "C. 幂次定律", "D. 指数分布"], "a": "C", "e": "无标度网络的连接分布遵循幂次定律，即任何节点与其他k个节点相连接的概率正比于k^-γ。", "kp": "ch09_s0_21"}, {"id": "ch09_mcq_7", "mod": "第九章 系统生物学", "modI": 0, "q": "幽门螺杆菌蛋白质相互作用网络研究中，Rain等使用的主要技术是：", "o": ["A. 酵母双杂交", "B. 质谱", "C. RNA-seq", "D. 芯片"], "a": "A", "e": "Rain等使用酵母双杂交策略从编码基因组多肽文库中筛选了261个蛋白质。", "kp": "ch09_s0_22"}, {"id": "ch09_mcq_8", "mod": "第九章 系统生物学", "modI": 0, "q": "虚拟细胞E-CELL是在哪所大学建立的？", "o": ["A. 美国康涅狄格大学", "B. 日本Keio大学", "C. 美国西雅图系统生物学研究所", "D. 英国剑桥大学"], "a": "B", "e": "E-CELL是Masura Tomita于1997年领导的研究小组在日本Keio大学成功建立的世界上第一个虚拟细胞模型。", "kp": "ch09_s0_30"}, {"id": "ch09_mcq_9", "mod": "第九章 系统生物学", "modI": 0, "q": "Cytoscape软件主要用于：", "o": ["A. 序列比对", "B. 分子互作网络可视化和复杂网络分析", "C. 基因预测", "D. 蛋白质结构预测"], "a": "B", "e": "Cytoscape是由美国西雅图系统生物学研究所开发的开源软件，主要用于分子互作网络可视化和复杂网络分析。", "kp": "ch09_s0_31"}, {"id": "ch09_mcq_10", "mod": "第九章 系统生物学", "modI": 0, "q": "在系统生物学中，鲁棒性是指：", "o": ["A. 系统对输入变化的响应依赖整体输入值", "B. 系统的输出对其输入或生物化学参数的个别选择不敏感", "C. 系统总是保持恒定输出", "D. 系统对任何扰动都无响应"], "a": "B", "e": "鲁棒性意指系统的输出对其输入或生物化学参数的个别选择不敏感。", "kp": "ch09_s0_13"}], "judge": [{"id": "ch09_judge_1", "modI": 0, "q": "系统生物学与传统实验生物学一样，仅关心个别基因或蛋白质。", "a": "错", "e": "系统生物学不同于传统实验生物学仅关心个别基因或蛋白质，而是研究所有基因、所有蛋白质以及组分间的所有相互关系。", "kp": "ch09_s0_3"}, {"id": "ch09_judge_2", "modI": 0, "q": "还原论是20世纪后半叶生物学发展的主流，其方法是为了研究生物系统某一方面的功能，只需寻找并鉴定出与此功能直接相关的基因或蛋白质即可。", "a": "对", "e": "还原论方法即从整体机能到分子机制，寻找并鉴定直接相关的基因或蛋白质。", "kp": "ch09_s0_1"}, {"id": "ch09_judge_3", "modI": 0, "q": "生物信息层次中，信息通过复杂网络执行，并且网络中存在枢纽节点。", "a": "对", "e": "生物信息具有多层次性、信息通过复杂网络执行、鲁棒性、网络中存在枢纽节点等性质。", "kp": "ch09_s0_28"}, {"id": "ch09_judge_4", "modI": 0, "q": "系统生物学测量全面性中的时空完备性是指对转录水平、蛋白质相互作用强度、磷酸化等特征的全面测量。", "a": "错", "e": "时空完备性是指精细时间序列和特定空间分布下获得系统行为；对转录水平、蛋白质相互作用强度、磷酸化、甲基化、乙酰化、定位等特征的全面测量属于内容的全面性。", "kp": "ch09_s0_4"}, {"id": "ch09_judge_5", "modI": 0, "q": "系统结构鉴定包括网络结构的鉴定和参数鉴定，其中自下而上的方法由分子水平的实验数据开始，将生物系统的相关分子视为整体。", "a": "错", "e": "自下而上的方法由分子之间的相互作用属性开始，研究这些相互作用如何导致生物体的功能行为；自上而下的方法由分子水平的实验数据开始，将生物系统的相关分子视为整体。", "kp": "ch09_s0_5"}, {"id": "ch09_judge_6", "modI": 0, "q": "基于DBRF方法，如果基因a的缺失导致基因b表达改变，则推测a调控b。", "a": "对", "e": "DBRF方法通过野生型和突变型基因表达的差异，由表达矩阵M导出交互矩阵IT，若基因a缺失导致基因b表达改变，则推测a调控b。", "kp": "ch09_s0_8"}, {"id": "ch09_judge_7", "modI": 0, "q": "基因调控网络数学模型中，有向边权重因子的正负代表作用于目标基因的激活或抑制。", "a": "对", "e": "节点代表基因，有向边代表调控关系，有向边权重因子的正负代表作用于目标基因的激活或抑制。", "kp": "ch09_s0_8"}, {"id": "ch09_judge_8", "modI": 0, "q": "无标度网络是1998年Barabasi等在研究WWW网络结构时意外发现的，其连接分布遵循泊松分布。", "a": "错", "e": "无标度网络的连接分布遵循“幂次定律”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ；泊松分布是随机网络的特征。", "kp": "ch09_s0_5"}, {"id": "ch09_judge_9", "modI": 0, "q": "幽门螺杆菌蛋白质相互作用网络中，一个蛋白质参与的相互作用越多，这个蛋白质对细胞的生存也就越重要。", "a": "对", "e": "分析表明，一个蛋白质参与的相互作用越多，这个蛋白质对细胞的生存也就越重要。", "kp": "ch09_s0_22"}, {"id": "ch09_judge_10", "modI": 0, "q": "Cytoscape是由美国西雅图系统生物学研究所开发并于2002年发布的开源软件，主要用于分子互作网络可视化和复杂网络分析。", "a": "对", "e": "Cytoscape是开源软件，主要用于分子互作网络可视化和复杂网络分析，2002年发布。", "kp": "ch09_s0_31"}], "fill": [{"id": "ch09_fill_1", "modI": 0, "q": "系统生物学根据Leroy Hood的定义，研究一个生物系统中所有组成成分的构成，以及在________条件下这些组分间的相互关系。", "a": "特定", "kp": "ch09_s0_3"}, {"id": "ch09_fill_2", "modI": 0, "q": "生物信息层次为：DNA→mRNA→蛋白质→生物分子相互作用→通路→网络→细胞→组织→生物体→种群→________。", "a": "生态系统", "kp": "ch09_s0_24"}, {"id": "ch09_fill_3", "modI": 0, "q": "系统生物学测量全面性分为三类：组分全面性、________完备性和内容全面性。", "a": "时空", "kp": "ch09_s0_4"}, {"id": "ch09_fill_4", "modI": 0, "q": "系统结构鉴定包括网络结构的鉴定和________鉴定。", "a": "参数", "kp": "ch09_s0_5"}, {"id": "ch09_fill_5", "modI": 0, "q": "基于差异表达调控识别方法（DBRF）从基因表达水平的差异推测可能的基因网络，由表达矩阵M可以导出交互矩阵________。", "a": "IT", "kp": "ch09_s0_8"}, {"id": "ch09_fill_6", "modI": 0, "q": "基因调控网络数学模型中，基因a_n的表达水平由非线性________函数g_n决定。", "a": "Sigmoidal", "kp": "ch09_s0_8"}, {"id": "ch09_fill_7", "modI": 0, "q": "无标度网络的连接分布遵循“________”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ。", "a": "幂次定律", "kp": "ch09_s0_21"}, {"id": "ch09_fill_8", "modI": 0, "q": "Cytoscape是由美国西雅图系统生物学研究所开发并于________年发布的开源软件，主要用于分子互作网络可视化和复杂网络分析。", "a": "2002", "kp": "ch09_s0_31"}], "short": [{"id": "ch09_short_1", "modI": 0, "q": "简述系统生物学的定义与核心目标。", "a": "定义：系统生物学是后基因组时代生物信息学的前沿领域，通过整合基因、蛋白质、代谢物等组成成分之间的相互作用，理解细胞中复杂的生物系统。根据Leroy Hood的定义，系统生物学研究一个生物系统中所有组成成分的构成，以及在特定条件下这些组分间的相互关系。核心目标：通过系统扰动、检测响应、整合数据，最终形成描述系统结构和对扰动响应的动力学模型。特征：以整体性研究为特征，强调在系统层次上理解生物分子行为到生物系统特征功能之间的关系。", "kp": "ch09_s0_0"}, {"id": "ch09_short_2", "modI": 0, "q": "简述还原论与综合论的区别及系统生物学的研究思路。", "a": "还原论：20世纪后半叶生物学发展的主流，为研究生物系统某一方面的功能，只需寻找并鉴定出与此功能直接相关的基因或蛋白质即可，即从整体机能到分子机制。综合论：基因组计划揭开了综合论研究方法的序幕，综合论研究基因和各种生物大分子是怎样通过网络调控方式形成一个生物系统的。系统生物学研究思路：往往从一个简单分子模型开始，研究分子之间的非线性相互作用可以产生什么样的系统特点，通过将描述这些作用的方程参数化，最终实现对系统特点的真实估计；传统生物学关注一个一个的通路，而系统生物学则希望研究各个通路之间的相互作用，构成复杂的相互作用网络。", "kp": "ch09_s0_1"}, {"id": "ch09_short_3", "modI": 0, "q": "简述系统生物学测量全面性的三类内容。", "a": "①组分的全面性：诸如基因、蛋白质等成分必须得到全面测量；②时空完备性：精细时间序列和特定空间分布下获得系统行为对系统生物学更加重要；③内容的全面性：对诸如转录水平、蛋白质相互作用强度、磷酸化、甲基化、乙酰化、定位等特征的全面测量至关重要。系统意味着测量所得的数据必须一致、完整；精确定量的重要性不言而喻；将传统实验自动化，从而实现高质量、高通量的实验输出。", "kp": "ch09_s0_4"}, {"id": "ch09_short_4", "modI": 0, "q": "简述基于DBRF方法从稳态基因表达数据推测基因网络的基本步骤。", "a": "①通过野生型和突变型基因表达的差异，推测直接和间接的基因调控关系；②由表达矩阵M导出交互矩阵IT，IT矩阵的行表示调控基因，列表示目标基因；如果基因a的缺失导致基因b表达改变，则推测a调控b；③剪除冗余网络中的间接关系：对于每个基因，找出它们之间是否有一条以上途径；检查这些途径的调控影响作用是否一样；假如影响作用一样，剪除冗余途径；④基因表达数据主要有时序和稳态两种，可以使用信息论、遗传算法或模拟退火算法从时序表达数据建立调控网络。", "kp": "ch09_s0_8"}, {"id": "ch09_short_5", "modI": 0, "q": "简述细菌化学趋向系统中积分负反馈与完全适应的关系。", "a": "细菌趋向性表现出完全适应性：随诱导物剂量的持续作用，输出首先有短暂升高，接着是一段适应期，之后返回到刺激前的活性水平。Barkai和Leibler的模拟工作显示化学适应的鲁棒性是分子信号网络结构的结果。假设简单的二态模型——MCP-CheW-CheA蛋白复合物激活或失活，该模型可以理解实验已经观察到的多种行为。定义输入变化前后稳态输出比来描述化学趋向网络适应性精度。网络模型预测这个比值总是等于1，表明适应性精度是一个鲁棒性量。控制工程师很熟悉鲁棒性是积分负反馈的典型特征。积分负反馈机制中，修饰速率依赖于蛋白复合物的活性，不依赖于其各种修饰形式的浓度，输入改变后系统活性倾向于返回初始稳态。", "kp": "ch09_s0_14"}], "calc": [{"id": "ch09_calc_1", "modI": 0, "q": "论述系统生物学中网络结构鉴定的两种方法及其适用情况，并说明参数鉴定的重要性。", "a": "网络结构鉴定有两种方法：①自下而上的方法：由分子之间的相互作用属性开始，研究这些相互作用如何导致生物体的功能行为，适合于大多数基因及调控网络已经得到较好理解的情况；②自上而下的方法：由分子水平的实验数据开始，将生物系统的相关分子视为整体，在数据分析过程中得到关于生物体分子组成及功能的新假设。参数鉴定同样重要，因为所有计算结果必须与实际实验结果一致，鉴定出来的网络必须对系统响应、行为特征进行量化分析和仿真。大多数情况下，可以基于实验数据估计参数，方法包括穷举搜索、遗传算法、模拟退火等。", "steps": "要点：①自下而上方法定义与适用情况；②自上而下方法定义与适用情况；③参数鉴定重要性：计算结果与实际实验结果一致、量化分析和仿真；④参数估计方法：穷举搜索、遗传算法、模拟退火等。", "kp": "ch09_s0_5"}, {"id": "ch09_calc_2", "modI": 0, "q": "论述蛋白质相互作用网络的基本概念、网络类型及无标度网络的性质，并以幽门螺杆菌蛋白质相互作用网络为例说明Hub蛋白的生物学意义。", "a": "网络是一个图，是节点和连接节点的边的集合。节点可以是分子、基因或蛋白质，边是分子相互作用、遗传相互作用或其他的两个元素之间的关系。网络从结构上可分为随机（指数式）网络和无标度网络。传统的随机网络（如ER模型），尽管节点连接是随机设定的，但大部分节点的连接数目会大致相同，即节点的分布方式遵循泊松分布，有一个特征性的“平均数”。无标度网络是1998年Barabasi等在研究WWW网络结构时意外发现的，其连接分布遵循“幂次定律”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ。无标度网络是不均匀的，大多数节点只有一个或两个连接，但少数节点有大量连接，从而保证系统是全部连通的。这种高联通度的节点（蛋白质）称为Hub，它作为网络中的枢纽，在生物的进化与维系相互作用网络的稳定性等方面有着不可替代的作用。幽门螺杆菌蛋白质相互作用网络实例：人类胃肠道病原菌幽门螺杆菌（Helicobacter pylori）基因组大约包含1590个潜在的蛋白质或ORF。Rain等使用酵母双杂交策略从编码基因组多肽文库中筛选了261个蛋白质，共计有1200个相互作用（大约占全蛋白质组相互作用的46.6%）。他们发展了称为PIMRider的软件，可以实现图示及基于网络图的功能分析。初步分析表明，该网络具有无标度网络的特征，存在一些高度连接的Hub蛋白。这些Hub蛋白往往参与重要的生命活动，并发挥关键的生物学功能。分析表明，一个蛋白质参与的相互作用越多，这个蛋白质对细胞的生存也就越重要。", "steps": "要点：①网络定义：节点和边；②网络类型：随机网络与无标度网络；③随机网络：泊松分布、特征性“平均数”；④无标度网络：幂次定律、概率正比于k^-γ、不均匀、少数Hub节点保证连通；⑤Hub蛋白定义与作用：枢纽、进化与稳定性；⑥幽门螺杆菌实例：1590个ORF、261个蛋白质、1200个相互作用、46.6%、PIMRider、无标度特征、Hub蛋白重要性与细胞生存重要性。", "kp": "ch09_s0_21"}], "term": [{"id": "ch09_term_1", "modI": 0, "term": "Systems Biology", "def": "系统生物学：后基因组时代生物信息学前沿领域。要点：①研究生物系统中所有组成成分（基因、蛋白质、代谢物等）的构成；②研究特定条件下这些组分间的相互关系；③通过系统扰动、检测响应、整合数据，形成描述系统结构和对扰动响应的动力学模型；④以整体性研究为特征，强调从生物分子行为到生物系统特征功能之间的关系。", "kp": "ch09_s0_33"}, {"id": "ch09_term_2", "modI": 0, "term": "Reductionism", "def": "还原论：20世纪后半叶生物学主流方法。要点：①为研究生物系统某一功能，寻找并鉴定直接相关的基因或蛋白质；②研究路径从整体机能到分子机制；③取得巨大成功，但在后基因组时代需要与综合论结合。", "kp": "ch09_s0_33"}, {"id": "ch09_term_3", "modI": 0, "term": "Holism / Integrationism", "def": "综合论/整体论：基因组计划揭开了综合论研究方法的序幕。要点：①研究基因和各种生物大分子怎样通过网络调控方式形成生物系统；②系统生物学往往从简单分子模型开始，研究分子间非线性相互作用产生的系统特点；③通过方程参数化实现对系统特点的真实估计；④关注各通路之间的相互作用，构成复杂相互作用网络。", "kp": "ch09_s0_33"}, {"id": "ch09_term_4", "modI": 0, "term": "Biological Information Hierarchy", "def": "生物信息层次：生物系统包含两类信息：编码执行生物功能分子机器的基因，以及识别基因表达、调控相互作用的网络。层次为：DNA→mRNA→蛋白质→生物分子相互作用→通路→网络→细胞→组织→生物体→种群→生态系统。要点：①多层次性；②信息通过复杂网络执行；③鲁棒性；④网络中存在枢纽节点；⑤每个层次信息都对理解生命系统运行提供有用视角。", "kp": "ch09_s0_34"}, {"id": "ch09_term_5", "modI": 0, "term": "Comprehensiveness of Systems Biology Measurements", "def": "系统生物学测量的全面性：系统、全面、精确的测量是系统生物学实验的基本特征。要点：①组分全面性：基因、蛋白质等成分必须得到全面测量；②时空完备性：精细时间序列和特定空间分布下获得系统行为；③内容全面性：对转录水平、蛋白质相互作用强度、磷酸化、甲基化、乙酰化、定位等特征全面测量；④数据必须一致、完整；⑤精确定量；⑥传统实验自动化，实现高质量、高通量输出。", "kp": "ch09_s0_33"}, {"id": "ch09_term_6", "modI": 0, "term": "System Structure Identification", "def": "系统结构鉴定：理解生物学系统需首先鉴定系统结构，包括网络结构鉴定和参数鉴定。要点：①自下而上方法：由分子间相互作用属性开始，研究这些相互作用如何导致生物体功能行为，适合大多数基因及调控网络已较好理解的情况；②自上而下方法：由分子水平实验数据开始，将相关分子视为整体，在数据分析过程中得到关于生物体分子组成及功能的新假设；③参数鉴定使计算结果与实际实验结果一致，对系统响应、行为特征进行量化分析和仿真；④参数估计方法包括穷举搜索、遗传算法、模拟退火等。", "kp": "ch09_s0_33"}, {"id": "ch09_term_7", "modI": 0, "term": "DBRF (Differential Expression Regulation Identification)", "def": "基于差异表达调控识别方法：从基因表达水平差异推测可能的基因网络。要点：①通过野生型和突变型基因表达差异，推测直接和间接的基因调控关系；②由表达矩阵M导出交互矩阵IT，行表示调控基因，列表示目标基因；③若基因a缺失导致基因b表达改变，则推测a调控b；④剪除冗余网络中的间接关系：找出是否有一条以上途径、检查这些途径的调控影响作用是否一样、若一样则剪除冗余途径；⑤基因表达数据有时序和稳态两种，可用信息论、遗传算法或模拟退火算法从时序表达数据建立调控网络。", "kp": "ch09_s0_33"}, {"id": "ch09_term_8", "modI": 0, "term": "Gene Regulatory Network Mathematical Model", "def": "基因调控网络数学模型：可描述为包含N个节点a_n（n=0,1,...,N-1）具有权重的节点间有向边的结构图。要点：①节点代表基因，有向边代表调控关系；②有向边权重因子的正负代表作用于目标基因的激活或抑制；③基因a_n的表达水平由非线性Sigmoidal函数g_n决定；④方程：dv_i/dt = R_i g(Σ w_ij v_j + h_i) - λ_i v_i，其中v_i为基因a_i的表达水平，R_i为从基因a_i合成的最大速率，g(z)为Sigmoidal函数，w_ij为描述基因调控系数的连接权重矩阵，h_i总结普遍的转录因子上的效果，λ_i为基因a_i的产物mRNA降解速率；⑤推测网络性能评价指标是敏感性和特异性：敏感性为目标网络中的边同时也在推测网络中出现的百分比；特异性为推测网络中的边同时也在目标网络中出现的百分比。", "kp": "ch09_s0_33"}, {"id": "ch09_term_9", "modI": 0, "term": "Yeast Galactose Utilization System", "def": "酵母半乳糖利用系统：包含至少9个基因。要点：①4个编码催化转化半乳糖为葡萄糖-6-磷酸的分子（GAL1、GAL5、GAL7和GAL10）；②第5个编码控制系统状态的转运分子；③有半乳糖时系统开启，缺少半乳糖时系统关闭；④大量转录因子如GAL3、GAL4、GAL80和GAL6参与关/启调控；⑤构建了9个遗传扰动酵母株，每个删除一个不同基因，与野生型一起，在2%半乳糖有（+Gal）和无（-Gal）条件下稳定生长；⑥在20种扰动下，用全酵母基因组微阵列监视相对野生型mRNA表达的变化；⑦997个mRNA显示出在一个或多个扰动下浓度发生变化，对应的扰动基因分成16个不同的类。", "kp": "ch09_s0_33"}, {"id": "ch09_term_10", "modI": 0, "term": "Bacterial Chemotaxis", "def": "细菌化学趋向：细菌移向或离开化学源的过程。要点：①细菌在化学梯度下通过偏向随机行走、向前游动和随机再定位的变化而移动；②甲基接受化学趋向蛋白（MCP）共5个跨膜受体，有多个甲基化位点，其修饰状态控制信号转导；③MCP与CheW和激酶CheA形成信号复合体，CheA能自发磷酸化并转移磷酸，从而响应调控子CheY；④磷酸-CheY与鞭毛马达蛋白相互作用诱导顺时针旋转；⑤CheZ蛋白促进CheY的去磷酸化；⑥CheA也负责转移磷酸到CheB MCP甲基化酶；⑦激活的磷酸-CheB驱使MCP去甲基化，作为适应机制的一部分减少MCP-CheW-CheA复合物的激酶活性；⑧CheR是执行的甲基化转移酶；⑨化学趋向网络对不同吸引浓度适应的鲁棒性。", "kp": "ch09_s0_33"}, {"id": "ch09_term_11", "modI": 0, "term": "Integral Negative Feedback and Perfect Adaptation", "def": "积分负反馈与完全适应：细菌趋向性表现出完全适应性。要点：①随诱导物剂量的持续作用，输出首先有短暂升高，接着是一段适应期，之后返回到刺激前的活性水平；②Barkai和Leibler的模拟工作显示化学适应的鲁棒性是分子信号网络结构的结果；③简单二态模型——MCP-CheW-CheA蛋白复合物激活或失活，可理解实验已观察到的多种行为；④定义输入变化前后稳态输出比来描述化学趋向网络适应性精度；⑤网络模型预测这个比值总是等于1，表明适应性精度是一个鲁棒性量；⑥控制工程师熟悉鲁棒性是积分负反馈的典型特征；⑦积分负反馈机制中，修饰速率依赖于蛋白复合物的活性，不依赖于其各种修饰形式的浓度，输入改变后系统活性倾向于返回初始稳态。", "kp": "ch09_s0_33"}, {"id": "ch09_term_12", "modI": 0, "term": "Protein-Protein Interaction Network", "def": "蛋白质相互作用网络：网络是一个图，是节点和连接节点的边的集合。要点：①节点可以是分子、基因或蛋白质，边是分子相互作用、遗传相互作用或其他的两个元素之间的关系；②网络从结构上可分为随机（指数式）网络和无标度网络；③传统随机网络（如ER模型）节点连接随机设定，但大部分节点连接数目大致相同，节点分布遵循泊松分布，有一个特征性的“平均数”；④无标度网络是1998年Barabasi等在研究WWW网络结构时意外发现的，其连接分布遵循“幂次定律”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ；⑤无标度网络是不均匀的，大多数节点只有一个或两个连接，但少数节点有大量连接，从而保证系统是全部连通的；⑥高联通度的节点（蛋白质）称为Hub，作为网络中的枢纽，在生物进化与维系相互作用网络稳定性等方面有不可替代的作用。", "kp": "ch09_s0_33"}]}], "mcq": [{"id": "ch09_mcq_1", "mod": "第九章 系统生物学", "modI": 0, "q": "系统生物学的主要目标是：", "o": ["A. 研究单个基因的功能", "B. 通过整合大量组成成分之间的相互作用理解细胞中复杂的生物系统", "C. 仅研究蛋白质的结构", "D. 开发新的实验技术"], "a": "B", "e": "系统生物学的目的是通过整合大量包括基因、蛋白质和代谢物组成成分之间的相互作用理解细胞中复杂的生物系统。", "kp": "ch09_s0_0"}, {"id": "ch09_mcq_2", "mod": "第九章 系统生物学", "modI": 0, "q": "下列哪项不是系统生物学全面性测量的分类？", "o": ["A. 组分的全面性", "B. 时空完备性", "C. 内容的全面性", "D. 数据的随机性"], "a": "D", "e": "全面性分为组分的全面性、时空完备性和内容的全面性三类。", "kp": "ch09_s0_4"}, {"id": "ch09_mcq_3", "mod": "第九章 系统生物学", "modI": 0, "q": "在基因调控网络模型中，有向边权重因子的正负代表：", "o": ["A. 激活或抑制", "B. 表达水平高低", "C. 蛋白质浓度", "D. 降解速率"], "a": "A", "e": "有向边权重因子的正负代表作用于目标基因的激活或抑制。", "kp": "ch09_s0_9"}, {"id": "ch09_mcq_4", "mod": "第九章 系统生物学", "modI": 0, "q": "酵母半乳糖利用系统中，编码催化转化半乳糖为葡萄糖-6-磷酸的基因不包括：", "o": ["A. GAL1", "B. GAL5", "C. GAL7", "D. GAL4"], "a": "D", "e": "GAL4是转录因子，不是催化酶。催化酶包括GAL1、GAL5、GAL7和GAL10。", "kp": "ch09_s0_11"}, {"id": "ch09_mcq_5", "mod": "第九章 系统生物学", "modI": 0, "q": "细菌化学趋向中，磷酸化的CheY与鞭毛马达蛋白相互作用诱导：", "o": ["A. 逆时针旋转", "B. 顺时针旋转", "C. 停止旋转", "D. 随机旋转"], "a": "B", "e": "磷酸-CheY与鞭毛马达蛋白相互作用诱导顺时针旋转。", "kp": "ch09_s0_13"}, {"id": "ch09_mcq_6", "mod": "第九章 系统生物学", "modI": 0, "q": "无标度网络的连接分布遵循：", "o": ["A. 泊松分布", "B. 正态分布", "C. 幂次定律", "D. 指数分布"], "a": "C", "e": "无标度网络的连接分布遵循幂次定律，即任何节点与其他k个节点相连接的概率正比于k^-γ。", "kp": "ch09_s0_21"}, {"id": "ch09_mcq_7", "mod": "第九章 系统生物学", "modI": 0, "q": "幽门螺杆菌蛋白质相互作用网络研究中，Rain等使用的主要技术是：", "o": ["A. 酵母双杂交", "B. 质谱", "C. RNA-seq", "D. 芯片"], "a": "A", "e": "Rain等使用酵母双杂交策略从编码基因组多肽文库中筛选了261个蛋白质。", "kp": "ch09_s0_22"}, {"id": "ch09_mcq_8", "mod": "第九章 系统生物学", "modI": 0, "q": "虚拟细胞E-CELL是在哪所大学建立的？", "o": ["A. 美国康涅狄格大学", "B. 日本Keio大学", "C. 美国西雅图系统生物学研究所", "D. 英国剑桥大学"], "a": "B", "e": "E-CELL是Masura Tomita于1997年领导的研究小组在日本Keio大学成功建立的世界上第一个虚拟细胞模型。", "kp": "ch09_s0_30"}, {"id": "ch09_mcq_9", "mod": "第九章 系统生物学", "modI": 0, "q": "Cytoscape软件主要用于：", "o": ["A. 序列比对", "B. 分子互作网络可视化和复杂网络分析", "C. 基因预测", "D. 蛋白质结构预测"], "a": "B", "e": "Cytoscape是由美国西雅图系统生物学研究所开发的开源软件，主要用于分子互作网络可视化和复杂网络分析。", "kp": "ch09_s0_31"}, {"id": "ch09_mcq_10", "mod": "第九章 系统生物学", "modI": 0, "q": "在系统生物学中，鲁棒性是指：", "o": ["A. 系统对输入变化的响应依赖整体输入值", "B. 系统的输出对其输入或生物化学参数的个别选择不敏感", "C. 系统总是保持恒定输出", "D. 系统对任何扰动都无响应"], "a": "B", "e": "鲁棒性意指系统的输出对其输入或生物化学参数的个别选择不敏感。", "kp": "ch09_s0_13"}], "judge": [{"id": "ch09_judge_1", "modI": 0, "q": "系统生物学与传统实验生物学一样，仅关心个别基因或蛋白质。", "a": "错", "e": "系统生物学不同于传统实验生物学仅关心个别基因或蛋白质，而是研究所有基因、所有蛋白质以及组分间的所有相互关系。", "kp": "ch09_s0_3"}, {"id": "ch09_judge_2", "modI": 0, "q": "还原论是20世纪后半叶生物学发展的主流，其方法是为了研究生物系统某一方面的功能，只需寻找并鉴定出与此功能直接相关的基因或蛋白质即可。", "a": "对", "e": "还原论方法即从整体机能到分子机制，寻找并鉴定直接相关的基因或蛋白质。", "kp": "ch09_s0_1"}, {"id": "ch09_judge_3", "modI": 0, "q": "生物信息层次中，信息通过复杂网络执行，并且网络中存在枢纽节点。", "a": "对", "e": "生物信息具有多层次性、信息通过复杂网络执行、鲁棒性、网络中存在枢纽节点等性质。", "kp": "ch09_s0_28"}, {"id": "ch09_judge_4", "modI": 0, "q": "系统生物学测量全面性中的时空完备性是指对转录水平、蛋白质相互作用强度、磷酸化等特征的全面测量。", "a": "错", "e": "时空完备性是指精细时间序列和特定空间分布下获得系统行为；对转录水平、蛋白质相互作用强度、磷酸化、甲基化、乙酰化、定位等特征的全面测量属于内容的全面性。", "kp": "ch09_s0_4"}, {"id": "ch09_judge_5", "modI": 0, "q": "系统结构鉴定包括网络结构的鉴定和参数鉴定，其中自下而上的方法由分子水平的实验数据开始，将生物系统的相关分子视为整体。", "a": "错", "e": "自下而上的方法由分子之间的相互作用属性开始，研究这些相互作用如何导致生物体的功能行为；自上而下的方法由分子水平的实验数据开始，将生物系统的相关分子视为整体。", "kp": "ch09_s0_5"}, {"id": "ch09_judge_6", "modI": 0, "q": "基于DBRF方法，如果基因a的缺失导致基因b表达改变，则推测a调控b。", "a": "对", "e": "DBRF方法通过野生型和突变型基因表达的差异，由表达矩阵M导出交互矩阵IT，若基因a缺失导致基因b表达改变，则推测a调控b。", "kp": "ch09_s0_8"}, {"id": "ch09_judge_7", "modI": 0, "q": "基因调控网络数学模型中，有向边权重因子的正负代表作用于目标基因的激活或抑制。", "a": "对", "e": "节点代表基因，有向边代表调控关系，有向边权重因子的正负代表作用于目标基因的激活或抑制。", "kp": "ch09_s0_8"}, {"id": "ch09_judge_8", "modI": 0, "q": "无标度网络是1998年Barabasi等在研究WWW网络结构时意外发现的，其连接分布遵循泊松分布。", "a": "错", "e": "无标度网络的连接分布遵循“幂次定律”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ；泊松分布是随机网络的特征。", "kp": "ch09_s0_5"}, {"id": "ch09_judge_9", "modI": 0, "q": "幽门螺杆菌蛋白质相互作用网络中，一个蛋白质参与的相互作用越多，这个蛋白质对细胞的生存也就越重要。", "a": "对", "e": "分析表明，一个蛋白质参与的相互作用越多，这个蛋白质对细胞的生存也就越重要。", "kp": "ch09_s0_22"}, {"id": "ch09_judge_10", "modI": 0, "q": "Cytoscape是由美国西雅图系统生物学研究所开发并于2002年发布的开源软件，主要用于分子互作网络可视化和复杂网络分析。", "a": "对", "e": "Cytoscape是开源软件，主要用于分子互作网络可视化和复杂网络分析，2002年发布。", "kp": "ch09_s0_31"}], "fill": [{"id": "ch09_fill_1", "modI": 0, "q": "系统生物学根据Leroy Hood的定义，研究一个生物系统中所有组成成分的构成，以及在________条件下这些组分间的相互关系。", "a": "特定", "kp": "ch09_s0_3"}, {"id": "ch09_fill_2", "modI": 0, "q": "生物信息层次为：DNA→mRNA→蛋白质→生物分子相互作用→通路→网络→细胞→组织→生物体→种群→________。", "a": "生态系统", "kp": "ch09_s0_24"}, {"id": "ch09_fill_3", "modI": 0, "q": "系统生物学测量全面性分为三类：组分全面性、________完备性和内容全面性。", "a": "时空", "kp": "ch09_s0_4"}, {"id": "ch09_fill_4", "modI": 0, "q": "系统结构鉴定包括网络结构的鉴定和________鉴定。", "a": "参数", "kp": "ch09_s0_5"}, {"id": "ch09_fill_5", "modI": 0, "q": "基于差异表达调控识别方法（DBRF）从基因表达水平的差异推测可能的基因网络，由表达矩阵M可以导出交互矩阵________。", "a": "IT", "kp": "ch09_s0_8"}, {"id": "ch09_fill_6", "modI": 0, "q": "基因调控网络数学模型中，基因a_n的表达水平由非线性________函数g_n决定。", "a": "Sigmoidal", "kp": "ch09_s0_8"}, {"id": "ch09_fill_7", "modI": 0, "q": "无标度网络的连接分布遵循“________”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ。", "a": "幂次定律", "kp": "ch09_s0_21"}, {"id": "ch09_fill_8", "modI": 0, "q": "Cytoscape是由美国西雅图系统生物学研究所开发并于________年发布的开源软件，主要用于分子互作网络可视化和复杂网络分析。", "a": "2002", "kp": "ch09_s0_31"}], "short": [{"id": "ch09_short_1", "modI": 0, "q": "简述系统生物学的定义与核心目标。", "a": "定义：系统生物学是后基因组时代生物信息学的前沿领域，通过整合基因、蛋白质、代谢物等组成成分之间的相互作用，理解细胞中复杂的生物系统。根据Leroy Hood的定义，系统生物学研究一个生物系统中所有组成成分的构成，以及在特定条件下这些组分间的相互关系。核心目标：通过系统扰动、检测响应、整合数据，最终形成描述系统结构和对扰动响应的动力学模型。特征：以整体性研究为特征，强调在系统层次上理解生物分子行为到生物系统特征功能之间的关系。", "kp": "ch09_s0_0"}, {"id": "ch09_short_2", "modI": 0, "q": "简述还原论与综合论的区别及系统生物学的研究思路。", "a": "还原论：20世纪后半叶生物学发展的主流，为研究生物系统某一方面的功能，只需寻找并鉴定出与此功能直接相关的基因或蛋白质即可，即从整体机能到分子机制。综合论：基因组计划揭开了综合论研究方法的序幕，综合论研究基因和各种生物大分子是怎样通过网络调控方式形成一个生物系统的。系统生物学研究思路：往往从一个简单分子模型开始，研究分子之间的非线性相互作用可以产生什么样的系统特点，通过将描述这些作用的方程参数化，最终实现对系统特点的真实估计；传统生物学关注一个一个的通路，而系统生物学则希望研究各个通路之间的相互作用，构成复杂的相互作用网络。", "kp": "ch09_s0_1"}, {"id": "ch09_short_3", "modI": 0, "q": "简述系统生物学测量全面性的三类内容。", "a": "①组分的全面性：诸如基因、蛋白质等成分必须得到全面测量；②时空完备性：精细时间序列和特定空间分布下获得系统行为对系统生物学更加重要；③内容的全面性：对诸如转录水平、蛋白质相互作用强度、磷酸化、甲基化、乙酰化、定位等特征的全面测量至关重要。系统意味着测量所得的数据必须一致、完整；精确定量的重要性不言而喻；将传统实验自动化，从而实现高质量、高通量的实验输出。", "kp": "ch09_s0_4"}, {"id": "ch09_short_4", "modI": 0, "q": "简述基于DBRF方法从稳态基因表达数据推测基因网络的基本步骤。", "a": "①通过野生型和突变型基因表达的差异，推测直接和间接的基因调控关系；②由表达矩阵M导出交互矩阵IT，IT矩阵的行表示调控基因，列表示目标基因；如果基因a的缺失导致基因b表达改变，则推测a调控b；③剪除冗余网络中的间接关系：对于每个基因，找出它们之间是否有一条以上途径；检查这些途径的调控影响作用是否一样；假如影响作用一样，剪除冗余途径；④基因表达数据主要有时序和稳态两种，可以使用信息论、遗传算法或模拟退火算法从时序表达数据建立调控网络。", "kp": "ch09_s0_8"}, {"id": "ch09_short_5", "modI": 0, "q": "简述细菌化学趋向系统中积分负反馈与完全适应的关系。", "a": "细菌趋向性表现出完全适应性：随诱导物剂量的持续作用，输出首先有短暂升高，接着是一段适应期，之后返回到刺激前的活性水平。Barkai和Leibler的模拟工作显示化学适应的鲁棒性是分子信号网络结构的结果。假设简单的二态模型——MCP-CheW-CheA蛋白复合物激活或失活，该模型可以理解实验已经观察到的多种行为。定义输入变化前后稳态输出比来描述化学趋向网络适应性精度。网络模型预测这个比值总是等于1，表明适应性精度是一个鲁棒性量。控制工程师很熟悉鲁棒性是积分负反馈的典型特征。积分负反馈机制中，修饰速率依赖于蛋白复合物的活性，不依赖于其各种修饰形式的浓度，输入改变后系统活性倾向于返回初始稳态。", "kp": "ch09_s0_14"}], "calc": [{"id": "ch09_calc_1", "modI": 0, "q": "论述系统生物学中网络结构鉴定的两种方法及其适用情况，并说明参数鉴定的重要性。", "a": "网络结构鉴定有两种方法：①自下而上的方法：由分子之间的相互作用属性开始，研究这些相互作用如何导致生物体的功能行为，适合于大多数基因及调控网络已经得到较好理解的情况；②自上而下的方法：由分子水平的实验数据开始，将生物系统的相关分子视为整体，在数据分析过程中得到关于生物体分子组成及功能的新假设。参数鉴定同样重要，因为所有计算结果必须与实际实验结果一致，鉴定出来的网络必须对系统响应、行为特征进行量化分析和仿真。大多数情况下，可以基于实验数据估计参数，方法包括穷举搜索、遗传算法、模拟退火等。", "steps": "要点：①自下而上方法定义与适用情况；②自上而下方法定义与适用情况；③参数鉴定重要性：计算结果与实际实验结果一致、量化分析和仿真；④参数估计方法：穷举搜索、遗传算法、模拟退火等。", "kp": "ch09_s0_5"}, {"id": "ch09_calc_2", "modI": 0, "q": "论述蛋白质相互作用网络的基本概念、网络类型及无标度网络的性质，并以幽门螺杆菌蛋白质相互作用网络为例说明Hub蛋白的生物学意义。", "a": "网络是一个图，是节点和连接节点的边的集合。节点可以是分子、基因或蛋白质，边是分子相互作用、遗传相互作用或其他的两个元素之间的关系。网络从结构上可分为随机（指数式）网络和无标度网络。传统的随机网络（如ER模型），尽管节点连接是随机设定的，但大部分节点的连接数目会大致相同，即节点的分布方式遵循泊松分布，有一个特征性的“平均数”。无标度网络是1998年Barabasi等在研究WWW网络结构时意外发现的，其连接分布遵循“幂次定律”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ。无标度网络是不均匀的，大多数节点只有一个或两个连接，但少数节点有大量连接，从而保证系统是全部连通的。这种高联通度的节点（蛋白质）称为Hub，它作为网络中的枢纽，在生物的进化与维系相互作用网络的稳定性等方面有着不可替代的作用。幽门螺杆菌蛋白质相互作用网络实例：人类胃肠道病原菌幽门螺杆菌（Helicobacter pylori）基因组大约包含1590个潜在的蛋白质或ORF。Rain等使用酵母双杂交策略从编码基因组多肽文库中筛选了261个蛋白质，共计有1200个相互作用（大约占全蛋白质组相互作用的46.6%）。他们发展了称为PIMRider的软件，可以实现图示及基于网络图的功能分析。初步分析表明，该网络具有无标度网络的特征，存在一些高度连接的Hub蛋白。这些Hub蛋白往往参与重要的生命活动，并发挥关键的生物学功能。分析表明，一个蛋白质参与的相互作用越多，这个蛋白质对细胞的生存也就越重要。", "steps": "要点：①网络定义：节点和边；②网络类型：随机网络与无标度网络；③随机网络：泊松分布、特征性“平均数”；④无标度网络：幂次定律、概率正比于k^-γ、不均匀、少数Hub节点保证连通；⑤Hub蛋白定义与作用：枢纽、进化与稳定性；⑥幽门螺杆菌实例：1590个ORF、261个蛋白质、1200个相互作用、46.6%、PIMRider、无标度特征、Hub蛋白重要性与细胞生存重要性。", "kp": "ch09_s0_21"}], "term": [{"id": "ch09_term_1", "modI": 0, "term": "Systems Biology", "def": "系统生物学：后基因组时代生物信息学前沿领域。要点：①研究生物系统中所有组成成分（基因、蛋白质、代谢物等）的构成；②研究特定条件下这些组分间的相互关系；③通过系统扰动、检测响应、整合数据，形成描述系统结构和对扰动响应的动力学模型；④以整体性研究为特征，强调从生物分子行为到生物系统特征功能之间的关系。", "kp": "ch09_s0_33"}, {"id": "ch09_term_2", "modI": 0, "term": "Reductionism", "def": "还原论：20世纪后半叶生物学主流方法。要点：①为研究生物系统某一功能，寻找并鉴定直接相关的基因或蛋白质；②研究路径从整体机能到分子机制；③取得巨大成功，但在后基因组时代需要与综合论结合。", "kp": "ch09_s0_33"}, {"id": "ch09_term_3", "modI": 0, "term": "Holism / Integrationism", "def": "综合论/整体论：基因组计划揭开了综合论研究方法的序幕。要点：①研究基因和各种生物大分子怎样通过网络调控方式形成生物系统；②系统生物学往往从简单分子模型开始，研究分子间非线性相互作用产生的系统特点；③通过方程参数化实现对系统特点的真实估计；④关注各通路之间的相互作用，构成复杂相互作用网络。", "kp": "ch09_s0_33"}, {"id": "ch09_term_4", "modI": 0, "term": "Biological Information Hierarchy", "def": "生物信息层次：生物系统包含两类信息：编码执行生物功能分子机器的基因，以及识别基因表达、调控相互作用的网络。层次为：DNA→mRNA→蛋白质→生物分子相互作用→通路→网络→细胞→组织→生物体→种群→生态系统。要点：①多层次性；②信息通过复杂网络执行；③鲁棒性；④网络中存在枢纽节点；⑤每个层次信息都对理解生命系统运行提供有用视角。", "kp": "ch09_s0_34"}, {"id": "ch09_term_5", "modI": 0, "term": "Comprehensiveness of Systems Biology Measurements", "def": "系统生物学测量的全面性：系统、全面、精确的测量是系统生物学实验的基本特征。要点：①组分全面性：基因、蛋白质等成分必须得到全面测量；②时空完备性：精细时间序列和特定空间分布下获得系统行为；③内容全面性：对转录水平、蛋白质相互作用强度、磷酸化、甲基化、乙酰化、定位等特征全面测量；④数据必须一致、完整；⑤精确定量；⑥传统实验自动化，实现高质量、高通量输出。", "kp": "ch09_s0_33"}, {"id": "ch09_term_6", "modI": 0, "term": "System Structure Identification", "def": "系统结构鉴定：理解生物学系统需首先鉴定系统结构，包括网络结构鉴定和参数鉴定。要点：①自下而上方法：由分子间相互作用属性开始，研究这些相互作用如何导致生物体功能行为，适合大多数基因及调控网络已较好理解的情况；②自上而下方法：由分子水平实验数据开始，将相关分子视为整体，在数据分析过程中得到关于生物体分子组成及功能的新假设；③参数鉴定使计算结果与实际实验结果一致，对系统响应、行为特征进行量化分析和仿真；④参数估计方法包括穷举搜索、遗传算法、模拟退火等。", "kp": "ch09_s0_33"}, {"id": "ch09_term_7", "modI": 0, "term": "DBRF (Differential Expression Regulation Identification)", "def": "基于差异表达调控识别方法：从基因表达水平差异推测可能的基因网络。要点：①通过野生型和突变型基因表达差异，推测直接和间接的基因调控关系；②由表达矩阵M导出交互矩阵IT，行表示调控基因，列表示目标基因；③若基因a缺失导致基因b表达改变，则推测a调控b；④剪除冗余网络中的间接关系：找出是否有一条以上途径、检查这些途径的调控影响作用是否一样、若一样则剪除冗余途径；⑤基因表达数据有时序和稳态两种，可用信息论、遗传算法或模拟退火算法从时序表达数据建立调控网络。", "kp": "ch09_s0_33"}, {"id": "ch09_term_8", "modI": 0, "term": "Gene Regulatory Network Mathematical Model", "def": "基因调控网络数学模型：可描述为包含N个节点a_n（n=0,1,...,N-1）具有权重的节点间有向边的结构图。要点：①节点代表基因，有向边代表调控关系；②有向边权重因子的正负代表作用于目标基因的激活或抑制；③基因a_n的表达水平由非线性Sigmoidal函数g_n决定；④方程：dv_i/dt = R_i g(Σ w_ij v_j + h_i) - λ_i v_i，其中v_i为基因a_i的表达水平，R_i为从基因a_i合成的最大速率，g(z)为Sigmoidal函数，w_ij为描述基因调控系数的连接权重矩阵，h_i总结普遍的转录因子上的效果，λ_i为基因a_i的产物mRNA降解速率；⑤推测网络性能评价指标是敏感性和特异性：敏感性为目标网络中的边同时也在推测网络中出现的百分比；特异性为推测网络中的边同时也在目标网络中出现的百分比。", "kp": "ch09_s0_33"}, {"id": "ch09_term_9", "modI": 0, "term": "Yeast Galactose Utilization System", "def": "酵母半乳糖利用系统：包含至少9个基因。要点：①4个编码催化转化半乳糖为葡萄糖-6-磷酸的分子（GAL1、GAL5、GAL7和GAL10）；②第5个编码控制系统状态的转运分子；③有半乳糖时系统开启，缺少半乳糖时系统关闭；④大量转录因子如GAL3、GAL4、GAL80和GAL6参与关/启调控；⑤构建了9个遗传扰动酵母株，每个删除一个不同基因，与野生型一起，在2%半乳糖有（+Gal）和无（-Gal）条件下稳定生长；⑥在20种扰动下，用全酵母基因组微阵列监视相对野生型mRNA表达的变化；⑦997个mRNA显示出在一个或多个扰动下浓度发生变化，对应的扰动基因分成16个不同的类。", "kp": "ch09_s0_33"}, {"id": "ch09_term_10", "modI": 0, "term": "Bacterial Chemotaxis", "def": "细菌化学趋向：细菌移向或离开化学源的过程。要点：①细菌在化学梯度下通过偏向随机行走、向前游动和随机再定位的变化而移动；②甲基接受化学趋向蛋白（MCP）共5个跨膜受体，有多个甲基化位点，其修饰状态控制信号转导；③MCP与CheW和激酶CheA形成信号复合体，CheA能自发磷酸化并转移磷酸，从而响应调控子CheY；④磷酸-CheY与鞭毛马达蛋白相互作用诱导顺时针旋转；⑤CheZ蛋白促进CheY的去磷酸化；⑥CheA也负责转移磷酸到CheB MCP甲基化酶；⑦激活的磷酸-CheB驱使MCP去甲基化，作为适应机制的一部分减少MCP-CheW-CheA复合物的激酶活性；⑧CheR是执行的甲基化转移酶；⑨化学趋向网络对不同吸引浓度适应的鲁棒性。", "kp": "ch09_s0_33"}, {"id": "ch09_term_11", "modI": 0, "term": "Integral Negative Feedback and Perfect Adaptation", "def": "积分负反馈与完全适应：细菌趋向性表现出完全适应性。要点：①随诱导物剂量的持续作用，输出首先有短暂升高，接着是一段适应期，之后返回到刺激前的活性水平；②Barkai和Leibler的模拟工作显示化学适应的鲁棒性是分子信号网络结构的结果；③简单二态模型——MCP-CheW-CheA蛋白复合物激活或失活，可理解实验已观察到的多种行为；④定义输入变化前后稳态输出比来描述化学趋向网络适应性精度；⑤网络模型预测这个比值总是等于1，表明适应性精度是一个鲁棒性量；⑥控制工程师熟悉鲁棒性是积分负反馈的典型特征；⑦积分负反馈机制中，修饰速率依赖于蛋白复合物的活性，不依赖于其各种修饰形式的浓度，输入改变后系统活性倾向于返回初始稳态。", "kp": "ch09_s0_33"}, {"id": "ch09_term_12", "modI": 0, "term": "Protein-Protein Interaction Network", "def": "蛋白质相互作用网络：网络是一个图，是节点和连接节点的边的集合。要点：①节点可以是分子、基因或蛋白质，边是分子相互作用、遗传相互作用或其他的两个元素之间的关系；②网络从结构上可分为随机（指数式）网络和无标度网络；③传统随机网络（如ER模型）节点连接随机设定，但大部分节点连接数目大致相同，节点分布遵循泊松分布，有一个特征性的“平均数”；④无标度网络是1998年Barabasi等在研究WWW网络结构时意外发现的，其连接分布遵循“幂次定律”分布，即任何节点与其他k个节点相连接的概率正比于k^-γ；⑤无标度网络是不均匀的，大多数节点只有一个或两个连接，但少数节点有大量连接，从而保证系统是全部连通的；⑥高联通度的节点（蛋白质）称为Hub，作为网络中的枢纽，在生物进化与维系相互作用网络稳定性等方面有不可替代的作用。", "kp": "ch09_s0_33"}], "preview": {"main": "本章介绍系统生物学的基本概念、哲学基础、技术方法与典型应用。系统生物学通过整合基因、蛋白质、代谢物等组分及其相互作用，在生物、遗传或化学扰动下检测响应，整合数据形成动力学模型，从而理解细胞复杂生物系统。内容涵盖基因表达调控网络、代谢网络、信号转导途径和蛋白质相互作用网络，并介绍虚拟细胞与生物学网络的可视化分析工具。", "questions": ["系统生物学与传统还原论方法在研究思路上的核心区别是什么？后基因组时代为何需要综合论？", "系统生物学的基本工作流程包括哪四个步骤？如何通过扰动实验和数学模型整合多组学数据？", "基因表达调控网络、代谢网络和信号转导途径各有什么特点？海胆endol6和酵母GAL模型分别说明了什么？", "蛋白质相互作用网络有哪些基本性质？网络模体和网络主题如何帮助理解生物学功能？", "Cytoscape等工具如何用于生物学网络的构建、分析与可视化？虚拟细胞的概念和构建思路是什么？"]}, "appcards": [{"front": "应用/分析型问题：系统生物学与传统还原论方法在研究思路上的核心区别是什么？请结合后基因组时代的背景说明。", "back": "还原论主张研究某一功能只需寻找并鉴定直接相关的基因或蛋白质，即从整体机能到分子机制，是20世纪后半叶生物学主流。综合论则研究基因和生物大分子如何通过网络调控形成生物系统，强调从分子间非线性相互作用出发重构生物体。基因组计划揭开了综合论序幕，后基因组时代需要综合全部生物信息重构生物体，综合论将成为主流。系统生物学常从简单分子模型开始，研究分子间非线性相互作用，通过整合基因、蛋白质、代谢物等组分及其相互作用理解细胞复杂生物系统。", "points": "还原论定义；综合论定义；基因组计划与后基因组时代背景；系统生物学整合多组学与网络调控的核心思路", "mod": 0, "modName": "第九章 系统生物学", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：系统生物学的基本工作流程包括哪四个步骤？请以基因表达调控网络或代谢网络为例说明如何应用。", "back": "基本工作框架包括四步：（一）系统结构鉴定：确定选定生物系统的所有组分，描绘结构，包括基因调控网络的所有组成部分及每部分功能、相互作用和相关参数；（二）系统扰动与动态响应观测：通过基因破坏、基因过表达、环境变化等扰动引起动态反应，观测基因表达谱等变化；（三）整合各种水平的整体测量和数学模型：结合生物化学、遗传学等方法，整合数据形成描述系统结构及扰动响应的动力学模型；（四）模型预测与实验验证：用模型预测未知基因及相互作用，再通过实验验证。例如酵母半乳糖利用模型通过GAL2、GAL1、GAL7、GAL10、GAL5等基因及GAL3、GAL4、GAL80调控，结合20种扰动下GAL基因表达响应比较观察值与预测值。", "points": "四步框架名称；每步核心任务；扰动实验类型；整合测量与数学模型；以GAL网络为例说明预测与验证", "mod": 0, "modName": "第九章 系统生物学", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：什么是网络模体？它与网络主题有何区别？如何用网络模体概念推测蛋白质功能？", "back": "网络模体定义为网络中比随机网络更多出现的连接模式，是复杂网络的基本构件。网络主题则是在整合生物网络中由多种相互作用类型组合形成的、具有特定功能意义的局部连接模式。区别在于：模体强调统计显著富集的局部连接模式，主题强调多种相互作用结合产生的过程或功能。用网络模体概念推测蛋白质功能：若未知蛋白质参与与已知功能模块相同的模体，可推测其具有相似功能；Yeger-Lotem等分析由转录调控和蛋白质相互作用组成的整合网络，发现模体大多为2、3、4节点，说明网络主要由小模体组成，可据此进行功能推断。", "points": "网络模体定义；网络主题定义；二者区别；模体统计富集特征；功能推测逻辑；整合网络分析实例", "mod": 0, "modName": "第九章 系统生物学", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：Cytoscape在生物学网络构建、分析与可视化中有哪些主要功能？请结合操作流程说明。", "back": "Cytoscape是生物学网络构建、分析与可视化的常用工具。主要功能包括：（1）网络导入与查看：导入示例数据如galFiltered.sif，在可视化界面查看网络，使用Layouts菜单调整网络布局；（2）样式设置：在可视化区域右键点击唤出快捷菜单，对选中节点和连线样式单独设置；在控制面板Style栏实现网络全局、映射调整和选中节点/连线的样式设置；（3）网络分析：在菜单栏选择NetworkAnalyzer运行网络分析，在数据栏生成新列展示网络节点和连线的拓扑参数；（4）属性映射：使用导入表格操作加入附加表格文件，作为网络属性映射到对应节点或连线上；（5）插件支持：如BiNGO用于GO富集分析，Agilent Literature Search用于文献挖掘，可通过插件管理器搜索、下载、安装并运行。", "points": "网络导入与布局；节点连线样式设置；NetworkAnalyzer分析；属性映射；插件管理与典型插件；生物学网络研究意义", "mod": 0, "modName": "第九章 系统生物学", "level": "掌握", "src": "生成"}]};